// 自動生成: 07_オーディオ教材/tools/build_audio.py
window.APL_DATA_AUDIO = [{"id":"ep01","file":"ep01_exam-overview.mp3","title":"第1回 試験の全体像とCBT","summary":"応用情報技術者試験の科目Aと科目Bの形式、科目Bの選択のしかた、合格基準、CBT受験の注意点と勉強の進め方をつかみます。","related":["../00_はじめに/01_試験概要.md","../00_はじめに/02_学習計画と勉強法.md","../04_科目B対策/01_科目Bの全体戦略.md"],"duration":324.9,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。今日から、応用情報技術者試験を音声で学んでいくわね。","start":0.0,"end":6.09},{"s":"zundamon","t":"ずんだもんなのだ！ボク、試験の名前は知ってるけど、中身はよく分かってないのだ。","start":6.54,"end":12.75},{"s":"metan","t":"第1回は、試験の全体像と、2026年度から始まったCBT方式の話をするわ。","start":13.2,"end":19.92},{"s":"zundamon","t":"そもそも、応用情報ってどのくらいの難しさなのだ？","start":20.37,"end":24.49},{"s":"metan","t":"国家試験である情報処理技術者試験のひとつで、レベル3にあたるわ。基本情報技術者の一つ上よ。","start":24.94,"end":31.91},{"s":"metan","t":"出題範囲は、テクノロジ系、マネジメント系、ストラテジ系の3分野。技術だけでなく、経営や法務も出るの。","start":32.16,"end":40.41},{"s":"zundamon","t":"CBTって何なのだ？","start":40.86,"end":42.82},{"s":"metan","t":"コンピュータ・ベースド・テスティングの略で、テストセンターのパソコンで解答する方式よ。","start":43.27,"end":49.29},{"s":"metan","t":"2025年度までは紙の試験だったけれど、2026年度からCBTに移行したの。","start":49.54,"end":55.52},{"s":"metan","t":"実施は前期と後期の年2回。決められた期間の中から、会場と日時を選んで予約するわ。","start":55.77,"end":65.1},{"s":"zundamon","t":"午前の試験と午後の試験があるって聞いたのだ。","start":65.55,"end":68.76},{"s":"metan","t":"CBTになって名前が変わったの。旧午前が科目A、旧午後が科目Bよ。","start":69.21,"end":74.79},{"s":"metan","t":"注意したいのは、科目Aと科目Bが別の期間に実施されること。同じ日に続けて受けるわけではないの。","start":75.04,"end":81.75},{"s":"zundamon","t":"じゃあ、申し込みも別々なのだ？","start":82.2,"end":84.95},{"s":"metan","t":"いいえ。申し込みは各期1回だけで、科目Aと科目Bの日時を同時に予約するのよ。","start":85.4,"end":91.53},{"s":"metan","t":"では中身ね。科目Aは150分で、四つの選択肢から一つを選ぶ問題が80問。80問すべてに答えるわ。","start":91.78,"end":100.3},{"s":"metan","t":"内訳の目安は、テクノロジ系が約50問、マネジメント系が約10問、ストラテジ系が約20問よ。","start":100.55,"end":108.13},{"s":"zundamon","t":"科目Bはどうなのだ？","start":108.58,"end":110.36},{"s":"metan","t":"科目Bも150分。記述式の問題が11問出て、そのうち5問に答えるの。","start":110.81,"end":116.63},{"s":"metan","t":"問1の情報セキュリティは必須。残りの問2から問11までの10問から、4問を選ぶわ。","start":116.88,"end":123.28},{"s":"zundamon","t":"つまり、セキュリティ1問と、自分で選んだ4問で、合計5問なのだ。","start":123.73,"end":129.72},{"s":"metan","t":"そのとおりよ。1問20点で、5問で100点満点。1問あたり30分が目安ね。","start":130.17,"end":136.38},{"s":"zundamon","t":"合格ラインは何点なのだ？","start":136.83,"end":139.02},{"s":"metan","t":"科目Aと科目B、それぞれ100点満点中60点以上で合格よ。","start":139.47,"end":144.28},{"s":"metan","t":"片方だけ高得点でもだめ。両方で60点以上が必要なの。","start":144.53,"end":148.9},{"s":"metan","t":"従来のルールでは、科目Aが基準点に届かないと、科目Bは採点されなかったわ。","start":149.15,"end":154.86},{"s":"metan","t":"CBT化の後の細かな採点ルールは、IPAの試験要綱で確認してね。","start":155.11,"end":160.43},{"s":"zundamon","t":"当日はどんなことに気をつければいいのだ？","start":160.88,"end":163.9},{"s":"metan","t":"一番大事なのは本人確認書類。受験票は送られてこないし、書類を出せないと受験できないわ。","start":164.35,"end":171.03},{"s":"metan","t":"画面にはメモ機能と電卓機能があって、入室時にはメモ用紙1枚と筆記用具も配られるわ。","start":171.28,"end":177.5},{"s":"metan","t":"科目Bの記述式はキーボード入力よ。普段からタイピングで答えを書く練習をしておくと安心ね。","start":177.75,"end":184.18},{"s":"zundamon","t":"勉強はどう進めればいいのだ？","start":184.63,"end":187.03},{"s":"metan","t":"科目Aは過去問中心。類題がよく出るから、なぜ他の選択肢が誤りかまで説明できるようにするの。","start":187.48,"end":197.24},{"s":"metan","t":"科目Bは、選ぶ分野を早めに決めること。必須のセキュリティに、得意な4分野と、予備を1つか2つね。","start":197.49,"end":204.9},{"s":"metan","t":"それから、インプット3にアウトプット7。読むだけでなく、問題を解いて弱点を見つけるのが大事よ。","start":205.15,"end":211.73},{"s":"zundamon","t":"学習時間はどのくらい必要なのだ？","start":212.18,"end":215.03},{"s":"metan","t":"基本情報に合格済みの人で約200時間、初めて学ぶ人なら約500時間と、よく言われるわ。","start":215.48,"end":222.29},{"s":"metan","t":"ここでひっかけ注意。科目Bは11問すべてに答える試験ではないわ。必須1問と選択4問の、5問だけよ。","start":222.54,"end":230.54},{"s":"zundamon","t":"全部解こうとしないで、選んだ問題に時間を使うのだ。","start":230.99,"end":235.23},{"s":"metan","t":"では、ミニクイズよ。第1問。科目Bで必ず解答しなければならない分野は何かしら？","start":235.68,"end":242.16},{"s":"metan","t":"正解は、情報セキュリティよ。問1が必須で、残りの10問から4問を選ぶわ。","start":245.41,"end":251.27},{"s":"metan","t":"第2問。科目Aが55点、科目Bが80点だったら、合格かしら？","start":251.52,"end":257.22},{"s":"zundamon","t":"合計は135点で、平均すれば60点を超えてるのだ。でも……。","start":260.67,"end":266.44},{"s":"metan","t":"答えは不合格。合格基準は、科目Aと科目Bのそれぞれが60点以上よ。合計や平均ではないの。","start":266.89,"end":274.38},{"s":"metan","t":"第3問。CBT方式の試験当日、必ず持っていくものは何かしら？","start":274.63,"end":280.01},{"s":"metan","t":"正解は本人確認書類。受験票は届かないから、予約した日時と会場も自分で控えておいてね。","start":283.26,"end":290.29},{"s":"metan","t":"今日のまとめよ。一つ目。科目Aは150分で80問すべてに解答、科目Bは150分で11問中5問に解答。","start":290.54,"end":299.45},{"s":"metan","t":"二つ目。科目Bは問1のセキュリティが必須で、ほかに4問を選ぶ。合格は両方とも60点以上。","start":299.7,"end":306.88},{"s":"metan","t":"三つ目。CBTでは科目Aと科目Bが別の期間。本人確認書類を忘れず、キーボード入力に慣れておくこと。","start":307.13,"end":315.21},{"s":"zundamon","t":"全体像が見えてきたのだ！次回からいよいよ中身の勉強なのだ。","start":315.66,"end":320.5},{"s":"metan","t":"次回は、基数変換と2の補数よ。またね。","start":320.95,"end":324.12}]},{"id":"ep02","file":"ep02_radix-complement.mp3","title":"第2回 基数変換と2の補数","summary":"10進数と2進数・16進数の変換手順と、負の数を表す2の補数の作り方・表現範囲を、口頭でたどれる例で学びます。","related":["../01_テクノロジ系/01_基礎理論.md","../05_まとめ・横断資料/01_計算問題公式集.md"],"duration":375.4,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第2回は、基数変換と2の補数を学ぶわ。","start":0.0,"end":5.19},{"s":"zundamon","t":"ずんだもんなのだ。2進数って、0と1しか出てこないあれなのだ？","start":5.64,"end":10.8},{"s":"metan","t":"そう。コンピュータの中は0と1の2進数で動いているの。計算問題の基本になるわよ。","start":11.25,"end":17.47},{"s":"zundamon","t":"そもそも、基数って何なのだ？","start":17.92,"end":20.36},{"s":"metan","t":"何進数かを表す数のことよ。10進数なら、各桁の重みが1、10、100と、10倍ずつ増えるわね。","start":20.81,"end":29.25},{"s":"metan","t":"2進数なら、重みは右の桁から1、2、4、8と、2倍ずつ増えるの。","start":29.5,"end":36.2},{"s":"metan","t":"例えば2進数の1011。1が立っている桁の重みは8と2と1だから、足して10進数の11よ。","start":36.45,"end":49.69},{"s":"zundamon","t":"1の桁の重みを足せば、10進数に戻せるのだ。","start":50.14,"end":53.96},{"s":"metan","t":"逆に10進数を2進数にするときは、2で割り続けて、余りを下から読むの。","start":54.41,"end":59.53},{"s":"metan","t":"13でやってみましょう。13を2で割ると、6余り1。6を2で割ると、3余り0。","start":59.78,"end":66.45},{"s":"metan","t":"3を2で割ると、1余り1。1を2で割ると、0余り1。ここで終わりね。","start":66.7,"end":72.77},{"s":"metan","t":"余りを最後から順に読むと、1、1、0、1。だから13は、2進数で1101よ。","start":73.02,"end":85.65},{"s":"zundamon","t":"最後に出た余りが、一番上の桁になるのだ。","start":86.1,"end":89.74},{"s":"metan","t":"そうよ。検算すると、8と4と1で13。合っているわね。","start":90.19,"end":94.87},{"s":"zundamon","t":"小数のときはどうするのだ？","start":95.32,"end":97.47},{"s":"metan","t":"小数部は、2を掛け続けて、出てきた整数部を上から読むの。0.625で試すわね。","start":97.92,"end":104.43},{"s":"metan","t":"0.625を2倍すると1.25で、整数部は1。残りの0.25を2倍すると0.5で、整数部は0。","start":104.68,"end":113.21},{"s":"metan","t":"0.5を2倍すると1.0で、整数部は1。小数部が0になったので終わりよ。","start":113.46,"end":119.31},{"s":"metan","t":"上から読んで、0.625は2進数で0.101。0.5と0.125を足した値ね。","start":119.56,"end":131.68},{"s":"metan","t":"ここでひっかけ注意。10進数の0.1は、2進数では無限に続く循環小数になって、正確には表せないの。","start":131.93,"end":140.23},{"s":"metan","t":"2進数で正確に表せるのは、0.5や0.25、0.375のように、分母が2のべき乗になる小数よ。","start":140.48,"end":148.77},{"s":"zundamon","t":"16進数はどうなのだ？","start":149.22,"end":151.32},{"s":"metan","t":"2進数を下の桁から4ビットずつ区切って、1つの桁にするの。10から15は、AからFで表すわ。","start":151.77,"end":158.91},{"s":"metan","t":"例えば16進数の2Fは、2かける16に、Fの15を足して、10進数の47よ。","start":159.16,"end":169.8},{"s":"zundamon","t":"じゃあ、マイナスの数はどう表すのだ？コンピュータにはマイナスの記号がないのだ。","start":170.25,"end":176.39},{"s":"metan","t":"そこで使うのが2の補数よ。作り方は、全ビットを反転して、1を足す。これだけ。","start":176.84,"end":183.01},{"s":"metan","t":"マイナス5を8ビットで表してみましょう。まずプラス5は、0000 0101。","start":183.26,"end":194.31},{"s":"metan","t":"全ビットを反転すると、1111 1010。","start":194.56,"end":203.32},{"s":"metan","t":"これに1を足して、1111 1011。これがマイナス5よ。","start":203.57,"end":214.03},{"s":"zundamon","t":"0と1をひっくり返して、1を足すだけなのだ！","start":214.48,"end":218.16},{"s":"metan","t":"最上位ビットが1ならマイナスの数、と考えていいわ。10進数に戻すときのコツもあるの。","start":218.61,"end":224.58},{"s":"metan","t":"8ビットなら、最上位ビットの重みをマイナス128とみなすのよ。","start":224.83,"end":229.4},{"s":"metan","t":"さっきの数なら、マイナス128に、64、32、16、8、2、1を足して、マイナス5。すぐ戻せるわね。","start":229.65,"end":240.21},{"s":"zundamon","t":"表せる範囲は、どのくらいなのだ？","start":240.66,"end":243.5},{"s":"metan","t":"8ビットの2の補数なら、マイナス128からプラス127までよ。","start":243.95,"end":248.77},{"s":"metan","t":"一般に、nビットなら、マイナス2のn−1乗から、2のn−1乗マイナス1までね。","start":249.02,"end":257.01},{"s":"metan","t":"符号なしの8ビットなら、0から255。どちらも256通りなのは同じよ。","start":257.26,"end":263.32},{"s":"metan","t":"ひっかけ注意その2。1の補数は反転するだけで、プラス0とマイナス0の2つができてしまうの。","start":263.57,"end":270.01},{"s":"metan","t":"2の補数なら0は1通り。だから今は2の補数が主流よ。","start":270.26,"end":274.22},{"s":"zundamon","t":"補数を使うと、何がうれしいのだ？","start":274.67,"end":277.66},{"s":"metan","t":"引き算を足し算で計算できることよ。回路を単純にできるの。","start":278.11,"end":282.06},{"s":"metan","t":"ではミニクイズ。第1問。10進数の6を、2進数にすると？","start":282.31,"end":287.43},{"s":"metan","t":"正解は110。6割る2は3余り0、3割る2は1余り1、1割る2は0余り1。下から読むわ。","start":290.68,"end":308.63},{"s":"metan","t":"第2問。8ビットの2の補数で表せる範囲は？","start":308.88,"end":312.36},{"s":"metan","t":"正解は、マイナス128からプラス127。マイナス側が1つ多いのがポイントよ。","start":315.61,"end":321.86},{"s":"metan","t":"第3問。マイナス1を、8ビットの2の補数で表すと？","start":322.11,"end":326.38},{"s":"zundamon","t":"プラス1を反転すると、最後の桁だけ0。それに1を足すと……全部1なのだ！","start":330.83,"end":337.42},{"s":"metan","t":"正解。8ビットすべて1よ。全ビット1はマイナス1、と覚えておくと便利ね。","start":337.87,"end":343.74},{"s":"metan","t":"まとめよ。一つ目。2進数へは、整数部は2で割って余りを下から、小数部は2を掛けて整数部を上から読む。","start":343.99,"end":351.88},{"s":"metan","t":"二つ目。16進数は2進数を4ビットずつ区切る。0.1のような小数は、2進数で正確に表せない。","start":352.13,"end":360.1},{"s":"metan","t":"三つ目。2の補数は全ビット反転して1を足す。8ビットの範囲は、マイナス128からプラス127。","start":360.35,"end":368.0},{"s":"zundamon","t":"反転して1を足す。もう忘れないのだ！","start":368.45,"end":371.51},{"s":"metan","t":"次回は、稼働率とRAIDよ。またね。","start":371.96,"end":374.61}]},{"id":"ep03","file":"ep03_availability-raid.mp3","title":"第3回 稼働率とRAID","summary":"MTBF・MTTRから稼働率を求める方法、直列・並列システムの稼働率、RAIDの各レベルの特徴と実効容量を学びます。","related":["../01_テクノロジ系/04_システム構成要素.md","../05_まとめ・横断資料/01_計算問題公式集.md"],"duration":302.6,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第3回は、稼働率とRAIDを学ぶわ。","start":0.0,"end":4.85},{"s":"zundamon","t":"ずんだもんなのだ。システムが止まらないようにする話なのだ？","start":5.3,"end":9.56},{"s":"metan","t":"そうよ。信頼性の計算は科目Aの定番で、公式を知っていれば確実に取れる得点源なの。","start":10.01,"end":16.61},{"s":"zundamon","t":"稼働率って、どうやって求めるのだ？","start":17.06,"end":20.0},{"s":"metan","t":"まず用語を2つ覚えましょう。MTBFは平均故障間隔。直ってから次に壊れるまでの、平均の稼働時間よ。","start":20.45,"end":28.82},{"s":"metan","t":"MTTRは平均修復時間。壊れてから直るまでの、平均の時間ね。","start":29.07,"end":34.64},{"s":"metan","t":"稼働率 ＝ MTBF ÷（MTBF ＋ MTTR）","start":34.89,"end":40.87},{"s":"metan","t":"例えばMTBFが480時間、MTTRが20時間なら、480を500で割って、0.96よ。","start":41.12,"end":50.08},{"s":"zundamon","t":"動いている時間を、全部の時間で割ってるだけなのだ。","start":50.53,"end":54.49},{"s":"metan","t":"そのとおり。だから稼働率を上げるには、MTBFを長くするか、MTTRを短くするの。","start":54.94,"end":61.8},{"s":"zundamon","t":"装置が2台あるときは、どうなるのだ？","start":62.25,"end":65.18},{"s":"metan","t":"つなぎ方で2通りあるわ。まずは直列。全部の装置が動いているときだけ、システムが動く構成よ。","start":65.63,"end":72.65},{"s":"metan","t":"直列の稼働率は掛け算。0.9の装置を2台直列にすると、0.9かける0.9で、0.81よ。","start":72.9,"end":81.54},{"s":"zundamon","t":"つなぐ装置が増えるほど、稼働率が下がっちゃうのだ。","start":81.99,"end":85.74},{"s":"metan","t":"次は並列。どれか1台でも動いていればよくて、全部が同時に壊れたときだけ止まる構成よ。","start":86.19,"end":92.5},{"s":"metan","t":"並列の稼働率は、1から、全部が同時に故障している確率を引いて求めるの。","start":92.75,"end":98.28},{"s":"metan","t":"0.9の装置2台なら、故障している確率はそれぞれ0.1。掛けると0.01。1から引いて0.99よ。","start":98.53,"end":106.75},{"s":"zundamon","t":"並列にすると、稼働率が上がるのだ！","start":107.2,"end":110.26},{"s":"metan","t":"直列と並列が混ざっているときは、内側の並列部分を1台の装置とみなして、直列の計算に使えばいいわ。","start":110.71,"end":118.26},{"s":"metan","t":"ひっかけ注意よ。並列のときに掛けるのは、稼働率ではなく、1から稼働率を引いた故障の確率の方。","start":118.51,"end":125.6},{"s":"metan","t":"覚え方は、直列は掛ける、並列は1から故障の積を引く。これで迷わないわ。","start":125.85,"end":131.54},{"s":"zundamon","t":"RAIDっていうのは何なのだ？","start":131.99,"end":134.06},{"s":"metan","t":"複数のディスクを組み合わせて1台のように扱い、高速化や信頼性の向上を図る技術よ。","start":134.51,"end":140.62},{"s":"metan","t":"RAID 0はストライピング。データを分散して書くから速いけれど、冗長性はないの。","start":140.87,"end":147.01},{"s":"metan","t":"だから1台でも壊れると、全部のデータを失ってしまうわ。","start":147.26,"end":151.3},{"s":"metan","t":"RAID 1はミラーリング。同じデータを2台に書くから、2台構成なら使える容量は1台分よ。","start":151.55,"end":158.39},{"s":"metan","t":"RAID 5は、データとパリティを全部のディスクに分散して書く方式。最低3台で、1台の故障まで耐えられるわ。","start":158.64,"end":166.73},{"s":"metan","t":"RAID 6は、2種類のパリティを分散するの。最低4台で、2台の故障まで耐えられるわ。","start":166.98,"end":173.7},{"s":"zundamon","t":"使える容量は、どうなるのだ？","start":174.15,"end":176.67},{"s":"metan","t":"同じ容量のディスクがn台なら、RAID 5はn−1台分、RAID 6はn−2台分。パリティの分だけ減るの。","start":177.12,"end":187.69},{"s":"metan","t":"例えば1テラバイトのディスク4台でRAID 5を組むと、3台分で3テラバイトね。","start":187.94,"end":193.39},{"s":"metan","t":"RAID 1+0は、ミラーリングしたものをストライピングする方式。使える容量は半分になるわ。","start":193.64,"end":202.99},{"s":"metan","t":"もう一つのひっかけ。RAIDはディスクの故障への対策で、バックアップの代わりにはならないの。","start":203.24,"end":209.18},{"s":"metan","t":"誤ってファイルを消すと、全部のディスクから同時に消えてしまうからよ。","start":209.43,"end":213.73},{"s":"zundamon","t":"故障には強いけど、うっかりミスには弱いのだ。","start":214.18,"end":217.86},{"s":"metan","t":"ではミニクイズ。第1問。MTBFが90時間、MTTRが10時間の装置の稼働率は？","start":218.31,"end":226.04},{"s":"metan","t":"正解は0.9。90と10を足した100で、90を割って、0.9よ。","start":229.29,"end":235.29},{"s":"metan","t":"第2問。稼働率0.8の装置を2台、並列につないだときの稼働率は？","start":235.54,"end":241.18},{"s":"zundamon","t":"故障の確率が0.2で、0.2かける0.2が0.04。1から引いて0.96なのだ！","start":245.63,"end":253.71},{"s":"metan","t":"正解よ。1台のときの0.8より、ぐっと上がったわね。","start":254.16,"end":258.47},{"s":"metan","t":"第3問。2テラバイトのディスク4台でRAID 5を組んだときの、実効容量は？","start":258.72,"end":264.46},{"s":"metan","t":"正解は6テラバイト。4台から1台分を引いた3台分で、2かける3よ。","start":267.71,"end":273.23},{"s":"metan","t":"まとめよ。一つ目。稼働率は、MTBFを、MTBFとMTTRの合計で割る。","start":273.48,"end":280.56},{"s":"metan","t":"二つ目。直列は稼働率を掛ける。並列は1から、故障している確率の積を引く。","start":280.81,"end":286.78},{"s":"metan","t":"三つ目。RAID 5は1台、RAID 6は2台の故障まで耐える。そしてRAIDはバックアップの代わりにならない。","start":287.03,"end":295.04},{"s":"zundamon","t":"公式がすっきり頭に入ったのだ！","start":295.49,"end":297.95},{"s":"metan","t":"次回は、CPUの性能とキャッシュよ。またね。","start":298.4,"end":301.85}]},{"id":"ep04","file":"ep04_cpu-cache.mp3","title":"第4回 CPUの性能とキャッシュ","summary":"クロック周波数・CPI・MIPSの関係、キャッシュメモリの実効アクセス時間、パイプライン処理の所要サイクル数を、簡単な数値で計算できるようにします。","related":["../01_テクノロジ系/03_コンピュータ構成要素.md","../05_まとめ・横断資料/01_計算問題公式集.md"],"duration":290.4,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第4回は、CPUの性能とキャッシュメモリを学ぶわ。","start":0.0,"end":5.93},{"s":"zundamon","t":"ずんだもんなのだ。速いCPUって、何が速いのだ？","start":6.38,"end":10.96},{"s":"metan","t":"今日はそれを数字で表す方法よ。MIPS、CPI、実効アクセス時間、パイプライン。全部、科目Aの計算問題の常連ね。","start":11.41,"end":21.55},{"s":"metan","t":"まずクロック周波数。CPUの動作の基準になる信号が、1秒間に刻む回数よ。","start":21.8,"end":27.88},{"s":"metan","t":"2ギガヘルツなら、1秒に20億回。1クロックの時間は、その逆数で0.5ナノ秒ね。","start":28.13,"end":34.64},{"s":"zundamon","t":"1クロックで1命令ずつ進むのだ？","start":35.09,"end":37.89},{"s":"metan","t":"そうとは限らないの。1命令に平均何クロックかかるかを、CPIというわ。サイクル・パー・インストラクションの略よ。","start":38.34,"end":47.19},{"s":"metan","t":"命令の種類ごとにCPIが違うときは、CPIに出現する割合を掛けて足すの。","start":47.44,"end":53.14},{"s":"metan","t":"CPIが2の命令が半分、CPIが6の命令が半分なら、1たす3で、平均CPIは4ね。","start":53.39,"end":61.34},{"s":"zundamon","t":"MIPSっていうのは何なのだ？","start":61.79,"end":63.94},{"s":"metan","t":"1秒間に何百万命令を実行できるか、を表す数値よ。","start":64.39,"end":68.81},{"s":"metan","t":"求め方は簡単。クロック周波数をメガヘルツで表して、CPIで割り算するだけよ。","start":69.06,"end":74.99},{"s":"metan","t":"2ギガヘルツは2000メガヘルツ。平均CPIが4なら、2000割る4で、500MIPSよ。","start":75.24,"end":83.25},{"s":"zundamon","t":"CPIが大きいほど、1命令に時間がかかって遅いのだ。","start":83.7,"end":88.5},{"s":"metan","t":"そのとおり。単位のひっかけにも注意してね。ナノ秒は10のマイナス9乗秒、マイクロ秒は10のマイナス6乗秒よ。","start":88.95,"end":96.83},{"s":"zundamon","t":"キャッシュメモリって、何のためにあるのだ？","start":97.28,"end":100.32},{"s":"metan","t":"CPUと主記憶の速度差を埋めるためよ。間に、高速で小容量のメモリを置くの。","start":100.77,"end":106.65},{"s":"metan","t":"目的のデータがキャッシュにある割合をヒット率、ない割合をミス率というわ。","start":106.9,"end":111.69},{"s":"metan","t":"平均の速さは、実効アクセス時間で表すの。","start":111.94,"end":115.35},{"s":"metan","t":"実効アクセス時間 ＝ キャッシュの時間 × ヒット率 ＋ 主記憶の時間 ×（1 − ヒット率）","start":115.6,"end":125.63},{"s":"metan","t":"キャッシュが10ナノ秒、主記憶が60ナノ秒、ヒット率が90%なら、10かける0.9で9。","start":125.88,"end":132.93},{"s":"metan","t":"60かける0.1で6。合わせて15ナノ秒よ。","start":133.18,"end":136.64},{"s":"zundamon","t":"ほとんどキャッシュで済むから、主記憶だけより、ずっと速くなるのだ。","start":137.09,"end":141.99},{"s":"metan","t":"ひっかけ注意。ミスしたときに、キャッシュを調べた時間も足す、という前提の問題もあるの。問題文の条件をよく読んでね。","start":142.44,"end":150.74},{"s":"metan","t":"書込み方式も出るわ。キャッシュと主記憶の両方に書くのがライトスルー、キャッシュだけに書いて後で戻すのがライトバックよ。","start":150.99,"end":158.37},{"s":"zundamon","t":"パイプラインっていうのは何なのだ？","start":158.82,"end":161.23},{"s":"metan","t":"命令の実行を、取出し、解読、実行などの段階に分けて、少しずつずらして並行に処理する方式よ。","start":161.68,"end":169.44},{"s":"metan","t":"洗濯、乾燥、たたむ、を何回分も流れ作業でやるイメージね。","start":169.69,"end":174.48},{"s":"metan","t":"段数をk、命令数をnとすると、乱れがなければ、k たす n ひく 1 サイクルで終わるわ。","start":174.73,"end":184.9},{"s":"metan","t":"5段のパイプラインで10命令なら、5たす10ひく1で、14サイクル。","start":185.15,"end":190.0},{"s":"metan","t":"パイプラインなしだと、5かける10で50サイクルかかるわね。","start":190.25,"end":193.82},{"s":"zundamon","t":"最初の命令が終わるまでに5サイクル。そのあとは1サイクルごとに1命令ずつ終わるのだ！","start":194.27,"end":200.73},{"s":"metan","t":"上手な言い換えね。ただし、流れが乱れるハザードもあるの。","start":201.18,"end":205.24},{"s":"metan","t":"分岐命令で次の命令が決まらないのが制御ハザード。対策は分岐予測や投機実行よ。","start":205.49,"end":211.6},{"s":"metan","t":"ではミニクイズ。第1問。クロック周波数1ギガヘルツ、平均CPIが2のCPUは、何MIPS？","start":211.85,"end":221.27},{"s":"metan","t":"正解は500MIPS。1000メガヘルツを2で割るわ。","start":224.52,"end":229.07},{"s":"metan","t":"第2問。キャッシュ10ナノ秒、主記憶50ナノ秒、ヒット率80%のときの実効アクセス時間は？","start":229.32,"end":236.82},{"s":"zundamon","t":"10かける0.8で8、50かける0.2で10。足して18ナノ秒なのだ！","start":241.27,"end":247.68},{"s":"metan","t":"正解よ。","start":248.13,"end":248.93},{"s":"metan","t":"第3問。4段のパイプラインで6個の命令を実行すると、何サイクルかかるかしら？","start":249.18,"end":255.09},{"s":"metan","t":"正解は9サイクル。4たす6ひく1よ。","start":258.34,"end":261.51},{"s":"metan","t":"まとめよ。一つ目。MIPSは、メガヘルツで表したクロック周波数を、平均CPIで割る。","start":261.76,"end":268.54},{"s":"metan","t":"二つ目。実効アクセス時間は、キャッシュの時間とヒット率、主記憶の時間とミス率を、それぞれ掛けて足す。","start":268.79,"end":276.08},{"s":"metan","t":"三つ目。パイプラインの所要サイクルは、段数たす命令数ひく1。","start":276.33,"end":281.04},{"s":"zundamon","t":"CPUの速さが、数字で分かるようになったのだ！","start":281.49,"end":285.31},{"s":"metan","t":"次回は、OSのスケジューリングと仮想記憶よ。またね。","start":285.76,"end":289.62}]},{"id":"ep05","file":"ep05_os-virtual-memory.mp3","title":"第5回 OS：スケジューリングと仮想記憶・ページ置換","summary":"タスクの3つの状態とスケジューリング方式、仮想記憶とページフォールト、FIFOとLRUによるページ置換の違いを学びます。","related":["../01_テクノロジ系/05_ソフトウェア.md","../05_まとめ・横断資料/01_計算問題公式集.md"],"duration":312.6,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第5回は、OSのスケジューリングと仮想記憶を学ぶわ。","start":0.0,"end":5.93},{"s":"zundamon","t":"ずんだもんなのだ。OSって、パソコンの裏で何をしているのだ？","start":6.38,"end":11.35},{"s":"metan","t":"今日は、CPUを誰に使わせるかという話と、メモリを大きく見せる仕組みの話よ。どちらも科目Aの頻出ね。","start":11.8,"end":19.71},{"s":"metan","t":"まず、タスクには3つの状態があるの。実行可能状態、実行状態、待ち状態よ。","start":19.96,"end":26.6},{"s":"metan","t":"実行可能状態は、CPUさえもらえればすぐ動ける状態。順番待ちの列に並んでいるイメージね。","start":26.85,"end":33.74},{"s":"metan","t":"実行状態は、CPUを割り当てられて動いている状態。シングルコアなら1つだけよ。","start":33.99,"end":39.77},{"s":"metan","t":"待ち状態は、入出力の完了などを待っていて、CPUがあっても動けない状態ね。","start":40.02,"end":45.93},{"s":"zundamon","t":"入出力が終わったら、すぐ実行状態に戻れるのだ？","start":46.38,"end":50.68},{"s":"metan","t":"そこがひっかけよ。待ち状態から直接、実行状態には行けないの。まず実行可能状態に戻って、順番を待つわ。","start":51.13,"end":59.51},{"s":"metan","t":"実行可能なタスクにCPUを割り当てることを、ディスパッチというわ。","start":59.76,"end":64.12},{"s":"zundamon","t":"どのタスクから順番に動かすのだ？","start":64.57,"end":67.13},{"s":"metan","t":"それを決めるのがスケジューリングよ。代表的な方式を4つ紹介するわね。","start":67.58,"end":72.43},{"s":"metan","t":"1つ目は到着順。来た順に実行するだけね。","start":72.68,"end":75.99},{"s":"metan","t":"2つ目は処理時間順。処理時間の短いものから実行して、平均ターンアラウンドタイムが最小になる方式よ。","start":76.24,"end":83.66},{"s":"metan","t":"時刻0に、処理時間6のAと、2のBが同時に来たとしましょう。到着順でAから実行すると、Aが6、Bが8で終わるわ。","start":83.91,"end":93.14},{"s":"metan","t":"平均は、6たす8を2で割って7。短いBを先にすると、Bが2、Aが8で終わって、平均は5になるわね。","start":93.39,"end":101.88},{"s":"zundamon","t":"短い仕事を先に片づけると、みんなの待ち時間が減るのだ。","start":102.33,"end":107.03},{"s":"metan","t":"3つ目は優先度順。ただし、優先度の低いタスクがいつまでも動けない、飢餓状態が起こり得るわ。","start":107.48,"end":114.55},{"s":"metan","t":"その対策が、待った時間に応じて優先度を上げる、エージングよ。","start":114.8,"end":119.32},{"s":"metan","t":"4つ目はラウンドロビン。一定の時間ずつ順番に実行して、終わらなければ列の最後に戻すの。","start":119.57,"end":125.91},{"s":"zundamon","t":"次は仮想記憶なのだ。仮想って、本物じゃないのだ？","start":126.36,"end":130.74},{"s":"metan","t":"補助記憶を使って、実際の主記憶より大きなアドレス空間をプログラムに見せる仕組みよ。","start":131.19,"end":136.92},{"s":"metan","t":"主流のページング方式では、固定長のページという単位で管理して、必要なページだけを、主記憶に置くの。","start":137.17,"end":144.27},{"s":"metan","t":"参照したページが主記憶にないことを、ページフォールトというわ。このとき補助記憶から読み込むの。","start":144.52,"end":150.66},{"s":"metan","t":"主記憶が足りずに、ページの出し入ればかり起きて処理が進まなくなる現象が、スラッシングよ。","start":150.91,"end":156.9},{"s":"zundamon","t":"主記憶がいっぱいのときは、どのページを追い出すのだ？","start":157.35,"end":161.12},{"s":"metan","t":"それがページ置換アルゴリズムね。FIFOは、最も古くに読み込んだページを追い出すの。","start":161.57,"end":167.74},{"s":"metan","t":"LRUは、最後に使われてから最も時間が経っている、つまり一番長く使われていないページを追い出すわ。","start":167.99,"end":175.33},{"s":"metan","t":"例で比べましょう。ページ枠は3つ。ページを1、2、3の順に読み込み、次に1を参照してヒットしたとするわ。","start":175.58,"end":184.45},{"s":"metan","t":"続けてページ4が来ると、枠がいっぱいなので、1つ追い出す必要があるわね。","start":184.7,"end":189.83},{"s":"metan","t":"FIFOなら、読み込んだのが一番古い1を追い出すの。さっき使ったばかりでも関係ないわ。","start":190.08,"end":196.5},{"s":"metan","t":"LRUなら、1は直前に使ったので新しい扱い。一番長く使われていない2を追い出すわ。","start":196.75,"end":203.39},{"s":"zundamon","t":"FIFOは読み込んだ順番だけ、LRUは最後に使った順番で考えるのだ！","start":203.84,"end":210.44},{"s":"metan","t":"そのとおり。ヒットしたときに順番を更新するかどうかが、2つの違いよ。","start":210.89,"end":215.71},{"s":"metan","t":"ひっかけ注意。FIFOでは、ページ枠を増やしたのにページフォールトが増えることがあるの。ビレイディの異常というわ。","start":215.96,"end":223.84},{"s":"metan","t":"ではミニクイズ。第1問。待ち状態のタスクの入出力が完了したら、次はどの状態になるかしら？","start":224.09,"end":231.43},{"s":"metan","t":"正解は実行可能状態。直接、実行状態にはならないわ。","start":234.68,"end":239.33},{"s":"metan","t":"第2問。ページ枠3つに、ページ2、5、7の順で読み込み、そのあと2を参照したわ。","start":239.58,"end":246.66},{"s":"metan","t":"次にページ9が来たとき、LRUで追い出されるのはどのページかしら？","start":246.91,"end":251.66},{"s":"zundamon","t":"2はさっき使ったから残るのだ。一番長く使われていないのは5なのだ！","start":256.11,"end":261.36},{"s":"metan","t":"正解よ。もしFIFOなら、一番古く読み込んだ2が追い出されるわね。","start":261.81,"end":267.08},{"s":"metan","t":"第3問。スラッシングの対策を1つ答えて。","start":267.33,"end":270.57},{"s":"metan","t":"正解は、主記憶を増やすこと。または、同時に実行するプログラムの数、つまり多重度を減らすことよ。","start":273.82,"end":280.95},{"s":"metan","t":"まとめよ。一つ目。タスクは実行可能、実行、待ちの3状態。待ちから実行へは直接行けない。","start":281.2,"end":288.65},{"s":"metan","t":"二つ目。処理時間順は平均ターンアラウンドタイムが最小。優先度順の飢餓状態はエージングで防ぐ。","start":288.9,"end":295.94},{"s":"metan","t":"三つ目。FIFOは一番古く読み込んだページ、LRUは一番長く使われていないページを追い出す。","start":296.19,"end":303.71},{"s":"zundamon","t":"OSの裏方の仕事が、ちょっと分かったのだ！","start":304.16,"end":307.51},{"s":"metan","t":"次回は、データベースの正規化とSQLよ。またね。","start":307.96,"end":311.78}]},{"id":"ep06","file":"ep06_db-normalization-sql.mp3","title":"第6回 データベース：正規化とSQL","summary":"関数従属と第1〜第3正規形の考え方、SQLの句の実行順、WHEREとHAVINGの違い、NULLの扱いと結合の種類を学びます。","related":["../01_テクノロジ系/06_データベース.md"],"duration":298.0,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第6回は、データベースの正規化とSQLを学ぶわ。","start":0.0,"end":5.89},{"s":"zundamon","t":"ずんだもんなのだ。正規化って、なんだか難しそうな名前なのだ。","start":6.34,"end":11.3},{"s":"metan","t":"考え方はシンプルよ。同じデータをあちこちに書かないように、表を分けることなの。","start":11.75,"end":17.11},{"s":"zundamon","t":"どうして表を分ける必要があるのだ？","start":17.56,"end":20.23},{"s":"metan","t":"受注の表に、商品名と単価も毎回書いていると考えて。ペンの単価を変えるとき、何行も直さないといけないわ。","start":20.68,"end":28.62},{"s":"metan","t":"1行でも直し忘れると、データが食い違うわね。これを更新異状というの。","start":28.87,"end":34.2},{"s":"metan","t":"ほかにも、受注がまだない新商品を登録できない挿入異状や、受注を消すと顧客の情報まで消える削除異状があるわ。","start":34.45,"end":42.47},{"s":"zundamon","t":"まとめて更新時異状なのだ。それを防ぐのが正規化なのだ。","start":42.92,"end":47.24},{"s":"metan","t":"正規化の前に、関数従属を押さえましょう。ある項目が決まると、別の項目が1つに決まる関係よ。","start":47.69,"end":55.05},{"s":"metan","t":"社員番号が決まれば、氏名は1つに決まるわね。でも氏名からは社員番号は決まらない。同姓同名がいるからよ。","start":55.3,"end":63.13},{"s":"metan","t":"では正規化の流れね。第1正規形は、繰り返しの項目をなくして、どの欄にも、データが1つだけ入る形よ。","start":63.38,"end":71.33},{"s":"metan","t":"受注明細の主キーが、受注番号と商品コードの組だとしましょう。","start":71.58,"end":76.06},{"s":"metan","t":"商品名は、商品コードだけで決まるわね。主キーの一部だけで決まる、これが部分関数従属よ。","start":76.31,"end":82.9},{"s":"metan","t":"部分関数従属をなくして、商品の表を別に分けたものが、第2正規形ね。","start":83.15,"end":88.55},{"s":"metan","t":"次に、受注番号で顧客コードが決まり、顧客コードで顧客名が決まる。こうした間接的な関係が、推移的関数従属よ。","start":88.8,"end":97.68},{"s":"metan","t":"推移的関数従属もなくして、顧客の表を分けたものが、第3正規形ね。","start":97.93,"end":103.21},{"s":"zundamon","t":"1が繰り返し、2が部分、3が推移、なのだ！","start":103.66,"end":108.19},{"s":"metan","t":"その覚え方で完璧よ。さらに厳しい、ボイス・コッド正規形もあるけれど、まずはこの3つね。","start":108.64,"end":115.46},{"s":"zundamon","t":"SQLは、データを取り出す命令なのだ？","start":115.91,"end":119.41},{"s":"metan","t":"そうよ。問合せのSELECT文で大事なのは、書く順番と、実行される順番が違うこと。","start":119.86,"end":128.49},{"s":"metan","t":"実行は、FROMで表を決め、WHEREで行を絞り、GROUP BYでグループにまとめるの。","start":128.74,"end":136.32},{"s":"metan","t":"そのあと、HAVINGでグループを絞り、SELECTで列を選び、最後にORDER BYで並べ替えるわ。","start":136.57,"end":144.6},{"s":"zundamon","t":"WHEREとHAVINGは、どっちも絞り込みなのだ？","start":145.05,"end":149.16},{"s":"metan","t":"WHEREはグループにする前の行を絞るもの。HAVINGはグループにした後で、グループを絞るものよ。","start":149.61,"end":158.0},{"s":"metan","t":"例えば、部門ごとの平均給与が300以上の部門だけ出したいなら、条件はHAVINGに書くわ。","start":158.25,"end":166.92},{"s":"metan","t":"ひっかけ注意よ。値が入っていないNULLを探すのに、イコールNULLと書いても、1行も選ばれないの。","start":167.17,"end":175.99},{"s":"metan","t":"NULLとの比較は、結果が不明になるからよ。必ずIS NULLと書いてね。","start":176.24,"end":182.8},{"s":"zundamon","t":"表どうしをつなぐ方法もあるのだ？","start":183.25,"end":185.86},{"s":"metan","t":"結合ね。内部結合は、両方の表で一致する行だけを残すの。","start":186.31,"end":192.71},{"s":"metan","t":"左外部結合は、左側の表の行をすべて残して、相手がない部分はNULLにするわ。","start":192.96,"end":202.4},{"s":"zundamon","t":"社員がいない部門も一覧に出したいなら、左外部結合なのだ。","start":202.85,"end":207.65},{"s":"metan","t":"ではミニクイズ。第1問。主キーが受注番号と商品コードの組のとき、商品コードだけで商品名が決まる関係を何というかしら？","start":208.1,"end":217.33},{"s":"metan","t":"正解は部分関数従属。これをなくすと第2正規形になるわ。","start":220.58,"end":224.91},{"s":"metan","t":"第2問。グループにまとめた後で、グループを絞り込む句は何かしら？","start":225.16,"end":229.96},{"s":"metan","t":"正解はHAVING。WHEREはグループにする前の行を絞るのよ。","start":233.21,"end":238.8},{"s":"metan","t":"第3問。部門コードがNULLの社員を探すのに、イコールNULLと書くと、何行選ばれるかしら？","start":239.05,"end":247.97},{"s":"zundamon","t":"比較の結果が不明になるから、0行なのだ！IS NULLを使うのだ。","start":251.42,"end":258.29},{"s":"metan","t":"正解よ。","start":258.74,"end":259.54},{"s":"metan","t":"まとめよ。一つ目。正規化は更新時異状を防ぐために表を分けること。1が繰り返し、2が部分、3が推移。","start":259.79,"end":268.36},{"s":"metan","t":"二つ目。SQLはFROM、WHERE、GROUP BY、HAVING、SELECT、ORDER BYの順に実行される。","start":268.61,"end":277.76},{"s":"metan","t":"三つ目。NULLの判定はIS NULL。内部結合は一致する行だけ、左外部結合は左の表をすべて残す。","start":278.01,"end":288.61},{"s":"zundamon","t":"表を分ける理由と、SQLの順番が分かったのだ！","start":289.06,"end":293.28},{"s":"metan","t":"次回は、トランザクションと障害回復よ。またね。","start":293.73,"end":297.21}]},{"id":"ep07","file":"ep07_db-transaction.mp3","title":"第7回 トランザクションと障害回復","summary":"ACID特性、ロストアップデートとロック（共有・専有、2相ロック、デッドロック）、ログを使ったロールバックとロールフォワードによる障害回復を学びます。","related":["../01_テクノロジ系/06_データベース.md"],"duration":281.7,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第7回は、トランザクションと障害回復を学ぶわ。","start":0.0,"end":5.64},{"s":"zundamon","t":"ずんだもんなのだ。トランザクションって、銀行の振込みみたいなものなのだ？","start":6.09,"end":11.56},{"s":"metan","t":"いい例ね。A口座から1万円を引いて、B口座に1万円を足す。この2つは、両方成功するか、両方取り消すかのどちらかでないと困るわ。","start":12.01,"end":22.28},{"s":"metan","t":"こうした一連の処理のまとまりがトランザクション。結果を確定するのがコミット、取り消すのがロールバックよ。","start":22.53,"end":29.06},{"s":"metan","t":"トランザクションが満たすべき性質を、ACID特性というの。4つの頭文字よ。","start":29.31,"end":35.84},{"s":"metan","t":"Aは原子性。全部実行されるか、まったく実行されないか。ロールバックで実現するわ。","start":36.09,"end":44.12},{"s":"metan","t":"Cは一貫性。実行の前後で、データの整合性が保たれることね。","start":44.37,"end":49.44},{"s":"metan","t":"Iは独立性。同時に実行しても、順番に実行したのと同じ結果になること。ロックで実現するわ。","start":49.69,"end":56.78},{"s":"metan","t":"Dは耐久性。コミットした結果は、障害が起きても失われないこと。ログとロールフォワードで実現するの。","start":57.03,"end":64.16},{"s":"zundamon","t":"同時に実行すると、何が困るのだ？","start":64.61,"end":67.84},{"s":"metan","t":"在庫が100個あって、T1が30個、T2が20個を出庫する場面で考えましょう。","start":68.29,"end":76.67},{"s":"metan","t":"2つがほぼ同時に100と読んで、T1が70を書き、続けてT2が80を書くと、在庫は80になってしまうわ。","start":76.92,"end":89.48},{"s":"zundamon","t":"本当は50個のはずなのだ。T1の更新が消えちゃったのだ！","start":89.93,"end":96.09},{"s":"metan","t":"これがロストアップデート。防ぐために、データに使用中の印を付けるロックを使うの。","start":96.54,"end":102.26},{"s":"metan","t":"ロックには2種類あるわ。読み取り用の共有ロックと、更新用の専有ロックよ。","start":102.51,"end":107.83},{"s":"metan","t":"共有ロックどうしなら、同時にかけられる。でも、どちらか一方でも専有ロックなら、後から来た方は待たされるの。","start":108.08,"end":115.5},{"s":"zundamon","t":"共有どうしだけ仲良し、なのだ。","start":115.95,"end":118.66},{"s":"metan","t":"そのとおり。それから2相ロック方式。ロックを獲得するだけの段階と、解除するだけの段階に分けるルールよ。","start":119.11,"end":126.45},{"s":"metan","t":"全員が従えば、順番に実行したのと同じ結果が保証されるわ。ただし、デッドロックは防げないの。","start":126.7,"end":133.8},{"s":"metan","t":"デッドロックは、お互いに相手のロック解除を待ち合って、どちらも進めなくなる状態よ。","start":134.05,"end":139.56},{"s":"metan","t":"予防には、全員がロックをかける順番をそろえる方法があるわ。起きてしまったら、どれかをロールバックして解消するの。","start":139.81,"end":147.4},{"s":"zundamon","t":"障害が起きたときは、どうやって元に戻すのだ？","start":147.85,"end":151.57},{"s":"metan","t":"ログファイルを使うの。ログには、更新前のデータと、更新後のデータが記録されているわ。","start":152.02,"end":158.01},{"s":"metan","t":"更新前のログで取り消すのがロールバック。更新後のログでやり直すのがロールフォワードよ。","start":158.26,"end":163.68},{"s":"zundamon","t":"前で戻す、後で進める、なのだ！","start":164.13,"end":167.23},{"s":"metan","t":"上手ね。さらにチェックポイントで、メモリ上の更新を定期的にディスクへ書き出しておくわ。","start":167.68,"end":173.45},{"s":"metan","t":"電源断のようなシステム障害では、チェックポイント以降のログだけを見ればいいので、回復が速くなるの。","start":173.7,"end":180.35},{"s":"metan","t":"障害の時点でコミット済みのトランザクションはロールフォワード。まだコミットしていないものはロールバックよ。","start":180.6,"end":186.71},{"s":"metan","t":"チェックポイントより前にコミットが終わっていたものは、ディスクに反映済みだから何もしなくていいわ。","start":186.96,"end":192.75},{"s":"metan","t":"ひっかけ注意。ディスクが壊れる媒体障害では、バックアップから復元して、更新後のログでロールフォワードするの。","start":193.0,"end":200.36},{"s":"metan","t":"だからログは、データベースとは別のディスクに置いておくことが大切よ。","start":200.61,"end":204.9},{"s":"metan","t":"ではミニクイズ。第1問。他のトランザクションが共有ロックをかけているデータに、専有ロックを要求したらどうなるかしら？","start":205.15,"end":213.31},{"s":"metan","t":"正解は、待たされる。同時にかけられるのは、共有ロックどうしだけよ。","start":216.56,"end":221.33},{"s":"metan","t":"第2問。システム障害の時点で、まだコミットしていなかったトランザクションは、どう回復するかしら？","start":221.58,"end":228.28},{"s":"zundamon","t":"更新前のログを使って、ロールバックするのだ！","start":231.73,"end":235.29},{"s":"metan","t":"正解よ。","start":235.74,"end":236.54},{"s":"metan","t":"第3問。データベースのディスクが故障したときの回復手順は？","start":236.79,"end":241.09},{"s":"metan","t":"正解は、バックアップから復元して、それ以降の更新後ログでロールフォワード。ロールバックではないわ。","start":245.34,"end":251.95},{"s":"metan","t":"まとめよ。一つ目。ACIDは原子性、一貫性、独立性、耐久性。","start":252.2,"end":258.41},{"s":"metan","t":"二つ目。共有ロックどうしだけ同時にかけられる。2相ロックでもデッドロックは防げない。","start":258.66,"end":264.1},{"s":"metan","t":"三つ目。更新前のログでロールバック、更新後のログでロールフォワード。媒体障害はバックアップとロールフォワード。","start":264.35,"end":271.89},{"s":"zundamon","t":"データベースが壊れても戻せる仕組みが分かったのだ！","start":272.34,"end":275.8},{"s":"metan","t":"次回は、ネットワークのTCP/IPとサブネットよ。またね。","start":276.25,"end":280.94}]},{"id":"ep08","file":"ep08_network-subnet.mp3","title":"第8回 ネットワーク：TCP/IPとサブネット","summary":"TCP/IPモデルの4つの層、TCPとUDPの違い、IPv4アドレスとサブネットマスク、ホスト数・ネットワークアドレス・ブロードキャストアドレスの求め方を学びます。","related":["../01_テクノロジ系/07_ネットワーク.md","../05_まとめ・横断資料/01_計算問題公式集.md"],"duration":314.3,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第8回は、ネットワークのTCP/IPとサブネットを学ぶわ。","start":0.0,"end":6.83},{"s":"zundamon","t":"ずんだもんなのだ。サブネットの計算、ボクは苦手なのだ……。","start":7.28,"end":11.72},{"s":"metan","t":"大丈夫。手順どおりにやれば必ず解けるわ。科目Aでも、科目Bのネットワークでも出る得点源よ。","start":12.17,"end":19.09},{"s":"metan","t":"まず全体像。インターネットで使われているTCP/IPモデルは、4つの層でできているの。","start":19.34,"end":25.98},{"s":"metan","t":"上から、アプリケーション層、トランスポート層、インターネット層、ネットワークインタフェース層よ。","start":26.23,"end":32.73},{"s":"metan","t":"HTTPやDNSはアプリケーション層、TCPとUDPはトランスポート層、IPはインターネット層ね。","start":32.98,"end":40.84},{"s":"zundamon","t":"TCPとUDPは、何が違うのだ？","start":41.29,"end":44.82},{"s":"metan","t":"TCPはコネクション型。通信の前に接続を確立して、順序制御や再送で信頼性を保つの。","start":45.27,"end":52.41},{"s":"metan","t":"接続の確立は、3ウェイハンドシェイク。SYN、SYNとACK、ACKの3回のやり取りよ。","start":52.66,"end":60.76},{"s":"metan","t":"UDPはコネクションレス型。再送はしないけれど、軽くて速いの。DNSの問合せやDHCP、音声や動画の配信で使うわ。","start":61.01,"end":70.88},{"s":"zundamon","t":"確実に届けたいならTCP、速さ優先ならUDP、なのだ。","start":71.33,"end":77.15},{"s":"metan","t":"次はIPアドレス。IPv4のアドレスは32ビットで、8ビットずつ区切って10進数で書くの。","start":77.6,"end":86.6},{"s":"metan","t":"前半がどのネットワークかを表すネットワーク部、後半がその中のどの機器かを表すホスト部よ。","start":86.85,"end":92.85},{"s":"zundamon","t":"どこまでがネットワーク部なのか、どうやって分かるのだ？","start":93.3,"end":97.12},{"s":"metan","t":"それを示すのがサブネットマスク。スラッシュの後ろの数字で、ネットワーク部のビット数を表す書き方もあるわ。","start":97.57,"end":104.5},{"s":"metan","t":"スラッシュ26なら、先頭の26ビットがネットワーク部。残りの6ビットがホスト部ね。","start":104.75,"end":110.62},{"s":"metan","t":"マスクの最後の区切りの数値は、128、192、224、240、248、252、254、255と変わっていくの。","start":110.87,"end":124.11},{"s":"zundamon","t":"1のビットが、左から1つずつ増えていくのだ。","start":124.56,"end":128.11},{"s":"metan","t":"そう。スラッシュ25が128、26が192、27が224よ。丸暗記より、その場で作れるようにしておくといいわ。","start":128.56,"end":138.95},{"s":"metan","t":"ホスト数は、2のホスト部ビット数乗から2を引くの。2の6乗は64で、引く2で62台よ。","start":139.2,"end":146.16},{"s":"zundamon","t":"どうして2を引くのだ？","start":146.61,"end":148.15},{"s":"metan","t":"ホスト部がすべて0のネットワークアドレスと、すべて1のブロードキャストアドレスは、機器に割り当てられないからよ。","start":148.6,"end":155.29},{"s":"metan","t":"では例題。192.168.10.130、スラッシュ26の、ネットワークアドレスを求めましょう。","start":155.54,"end":168.7},{"s":"metan","t":"スラッシュ26のマスクは、最後の区切りが192。ここで速算法を使うわ。","start":168.95,"end":176.42},{"s":"metan","t":"256からマスクの値の192を引いた64が、ブロックの大きさ。アドレスは64個ずつ区切られるの。","start":176.67,"end":187.41},{"s":"metan","t":"区切りは0、64、128、192。130以下で一番大きいのは128ね。","start":187.66,"end":195.78},{"s":"metan","t":"だからネットワークアドレスは、最後が128。ブロードキャストアドレスは、次の区切りの1つ手前で191よ。","start":196.03,"end":204.04},{"s":"zundamon","t":"128と191を除いた、129から190までが、機器に使えるアドレスなのだ！","start":204.49,"end":212.26},{"s":"metan","t":"そのとおり。ちょうど62個ね。","start":212.71,"end":214.88},{"s":"metan","t":"ひっかけ注意。ホスト数で2を引き忘れないこと。それから、伝送時間の計算ではバイトをビットにする8倍も忘れがちよ。","start":215.13,"end":223.17},{"s":"metan","t":"ではミニクイズ。第1問。スラッシュ27のネットワークに割り当てられるホストは何台かしら？","start":223.42,"end":231.65},{"s":"metan","t":"正解は30台。ホスト部が5ビットだから、2の5乗の32から2を引くわ。","start":234.9,"end":240.16},{"s":"metan","t":"第2問。192.168.1.70、スラッシュ26のネットワークアドレスの、最後の区切りの値は？","start":240.41,"end":254.39},{"s":"zundamon","t":"ブロックは64ずつだから、70以下で一番大きい区切りは64なのだ！","start":258.84,"end":264.8},{"s":"metan","t":"正解よ。ネットワークアドレスは、最後が64になるわ。","start":265.25,"end":269.53},{"s":"metan","t":"第3問。DNSの問合せで主に使われるのは、TCPとUDPのどちらかしら？","start":269.78,"end":276.1},{"s":"metan","t":"正解はUDP。軽くて速いコネクションレス型ね。","start":279.35,"end":283.1},{"s":"metan","t":"まとめよ。一つ目。TCPは接続を確立して信頼性を保つ。UDPは再送しない代わりに軽くて速い。","start":283.35,"end":291.32},{"s":"metan","t":"二つ目。ホスト数は、2のホスト部ビット数乗から2を引く。","start":291.57,"end":295.54},{"s":"metan","t":"三つ目。ネットワークアドレスは、256からマスクの値を引いたブロックの倍数で探す。","start":295.79,"end":304.37},{"s":"zundamon","t":"サブネットの計算、手順どおりならボクにもできたのだ！","start":304.82,"end":308.86},{"s":"metan","t":"次回は、暗号とデジタル署名、PKIよ。またね。","start":309.31,"end":313.47}]},{"id":"ep09","file":"ep09_crypto-pki.mp3","title":"第9回 暗号とデジタル署名・PKI","summary":"共通鍵暗号と公開鍵暗号、ハイブリッド暗号、ハッシュ関数、デジタル署名、PKIと証明書の失効確認を、「どの鍵で何をするか」を軸に整理します。","related":["../01_テクノロジ系/08_情報セキュリティ.md"],"duration":330.0,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第9回は「暗号とデジタル署名・PKI」を学ぶわね。","start":0.0,"end":6.82},{"s":"zundamon","t":"ずんだもんなのだ。鍵がたくさん出てきて、いつも頭がこんがらがるのだ。","start":7.27,"end":12.52},{"s":"metan","t":"今日は「どの鍵で何をするか」を、すっきり整理しましょう。","start":12.97,"end":17.72},{"s":"zundamon","t":"そもそも、共通鍵暗号と公開鍵暗号って、何が違うのだ？","start":18.17,"end":23.6},{"s":"metan","t":"共通鍵暗号は、暗号化と復号に同じ鍵を使う方式よ。代表はAESね。","start":24.05,"end":30.17},{"s":"metan","t":"処理は速いけれど、相手に鍵を安全に渡す方法が必要になるの。これを鍵配送問題というわ。","start":30.42,"end":37.24},{"s":"metan","t":"公開鍵暗号は、公開鍵と秘密鍵のペアを使うの。代表はRSAや楕円曲線暗号よ。","start":37.49,"end":44.47},{"s":"metan","t":"公開鍵は配ってよいから配送は楽。そのかわり処理は遅いわね。","start":44.72,"end":49.12},{"s":"zundamon","t":"必要な鍵の数も違うって聞いたのだ。","start":49.57,"end":52.39},{"s":"metan","t":"ええ。100人が互いに暗号通信するとき、共通鍵なら100×99÷2で、4,950個必要よ。","start":52.84,"end":61.52},{"s":"metan","t":"公開鍵なら1人1ペアだから、2×100で200個で済むわ。","start":61.77,"end":65.88},{"s":"zundamon","t":"速い共通鍵と、配送が楽な公開鍵。いいとこ取りはできないのだ？","start":66.33,"end":72.2},{"s":"metan","t":"それがハイブリッド暗号方式よ。TLSやS/MIMEで使われているわ。","start":72.65,"end":78.66},{"s":"metan","t":"本文は使い捨ての共通鍵で暗号化して、その共通鍵だけを受信者の公開鍵で暗号化して送るの。","start":78.91,"end":85.76},{"s":"metan","t":"受信者は自分の秘密鍵で共通鍵を取り出して、本文を復号するわけね。","start":86.01,"end":90.92},{"s":"zundamon","t":"重たい公開鍵暗号は、小さな共通鍵を運ぶ係なのだ！","start":91.37,"end":96.37},{"s":"metan","t":"その通りよ。","start":96.82,"end":97.66},{"s":"zundamon","t":"次はハッシュ関数なのだ。これも暗号の仲間なのだ？","start":98.11,"end":102.12},{"s":"metan","t":"ハッシュ関数は、任意の長さのデータから固定長のハッシュ値を作る関数よ。暗号化ではないの。","start":102.57,"end":108.79},{"s":"metan","t":"ハッシュ値から元のデータを求められない一方向性と、同じハッシュ値になる別のデータを見つけにくい衝突困難性があるわ。","start":109.04,"end":116.61},{"s":"metan","t":"代表はSHA-256。MD5やSHA-1は衝突が見つかっているから、新しい用途には使わないの。","start":116.86,"end":125.9},{"s":"zundamon","t":"デジタル署名は、どうやって動くのだ？","start":126.35,"end":129.35},{"s":"metan","t":"送信者は本文のハッシュ値を計算して、それを自分の秘密鍵で署名するの。","start":129.8,"end":134.86},{"s":"metan","t":"受信者は、送信者の公開鍵で署名を検証して取り出したハッシュ値と、受け取った本文から計算したハッシュ値を比べるわ。","start":135.11,"end":142.96},{"s":"metan","t":"一致すれば、本人が送ったもので改ざんもないと分かるの。あとから「送っていない」と言わせない否認防止もできるわね。","start":143.21,"end":150.9},{"s":"zundamon","t":"つまり、署名は送信者の秘密鍵、秘密に送るなら受信者の公開鍵、なのだ！","start":151.35,"end":158.15},{"s":"metan","t":"完璧よ。「機密性は受信者の鍵、署名は送信者の鍵」と覚えてね。","start":158.6,"end":163.92},{"s":"metan","t":"注意点として、署名だけでは本文は平文のまま。機密性は守れないわ。","start":164.17,"end":169.27},{"s":"zundamon","t":"共通鍵で作るMACでも、改ざんは分かるのだ？","start":169.72,"end":174.51},{"s":"metan","t":"分かるわ。でも送信者と受信者が同じ鍵を持つから、どちらが作ったか区別できないの。","start":174.96,"end":180.64},{"s":"metan","t":"だからMACでは否認防止はできない。これはよく出るひっかけよ。","start":180.89,"end":186.45},{"s":"zundamon","t":"でも、その公開鍵が本当に相手のものか、どうやって分かるのだ？","start":186.9,"end":192.16},{"s":"metan","t":"そこでPKI、公開鍵基盤の出番よ。認証局、つまりCAが本人確認をして、デジタル証明書を発行するの。","start":192.61,"end":201.42},{"s":"metan","t":"証明書には所有者の公開鍵や有効期間が書かれていて、CAのデジタル署名が付いているわ。","start":201.67,"end":208.04},{"s":"metan","t":"ブラウザは、サーバ証明書から中間CA、ルートCAへと署名をたどって検証するの。これが証明書チェーンね。","start":208.29,"end":216.08},{"s":"metan","t":"ルート証明書はOSやブラウザに最初から組み込まれていて、信頼の起点になるわ。","start":216.33,"end":221.66},{"s":"zundamon","t":"秘密鍵が漏れちゃったら、証明書はどうなるのだ？","start":222.11,"end":225.79},{"s":"metan","t":"有効期間内でも失効させるの。確認方法は二つ。CRLは、失効した証明書のシリアル番号の一覧よ。","start":226.24,"end":234.41},{"s":"metan","t":"OCSPは、証明書の状態をリアルタイムに問い合わせる方式ね。","start":234.66,"end":239.31},{"s":"metan","t":"ひっかけ注意。CRLに載るのは証明書そのものではなく、シリアル番号よ。","start":239.56,"end":245.09},{"s":"metan","t":"では、ミニクイズよ。第1問。Aさんが、Bさんだけが読めるように暗号化したい。使う鍵はどれかしら。","start":245.34,"end":252.93},{"s":"metan","t":"正解は、Bさんの公開鍵よ。対になるBさんの秘密鍵でしか復号できないからね。","start":256.68,"end":262.54},{"s":"metan","t":"第2問。完全性、否認防止、機密性。このうち、デジタル署名だけでは確保できないものは？","start":262.79,"end":270.22},{"s":"zundamon","t":"機密性なのだ！署名だけだと、本文は平文のままなのだ。","start":274.17,"end":278.88},{"s":"metan","t":"正解よ。","start":279.33,"end":280.13},{"s":"metan","t":"第3問。改ざんの検出はできるけれど、否認防止はできない仕組みは何かしら。","start":280.38,"end":285.78},{"s":"metan","t":"答えはMAC、メッセージ認証符号よ。共通鍵を使うから、作った人を区別できないの。","start":289.53,"end":296.68},{"s":"metan","t":"今日のまとめよ。一つ目。ハイブリッド暗号は、本文を共通鍵で、その共通鍵を受信者の公開鍵で暗号化する。","start":296.93,"end":305.29},{"s":"metan","t":"二つ目。署名は送信者の秘密鍵で作り、送信者の公開鍵で検証する。署名だけでは機密性はない。","start":305.54,"end":313.13},{"s":"metan","t":"三つ目。PKIでは、CAが署名した証明書で公開鍵の持ち主を保証し、失効はCRLやOCSPで確認する。","start":313.38,"end":322.59},{"s":"zundamon","t":"鍵の使い分け、ばっちりなのだ！","start":323.04,"end":325.65},{"s":"metan","t":"次回は、攻撃手法と対策よ。またね。","start":326.1,"end":329.15}]},{"id":"ep10","file":"ep10_web-attacks.mp3","title":"第10回 攻撃手法と対策","summary":"SQLインジェクション、XSS、CSRF、セッション固定化、パスワードリスト攻撃、ランサムウェアについて、攻撃の仕組みと根本的な対策をセットで覚えます。","related":["../01_テクノロジ系/08_情報セキュリティ.md"],"duration":288.2,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第10回は「攻撃手法と対策」。科目Bの問1でもよく出るテーマね。","start":0.0,"end":8.78},{"s":"zundamon","t":"ずんだもんなのだ。攻撃の名前がカタカナばかりで、ぜんぜん覚えられないのだ。","start":9.23,"end":14.95},{"s":"metan","t":"大丈夫。「仕組み」と「根本的な対策」をセットで覚えれば、ぐっと楽になるわ。","start":15.4,"end":21.61},{"s":"zundamon","t":"まず、SQLインジェクションって何なのだ？","start":22.06,"end":25.5},{"s":"metan","t":"入力欄にSQL文の一部を入れて、意図しないSQLを実行させる攻撃よ。データを盗んだり、改ざんしたりするの。","start":25.95,"end":34.35},{"s":"zundamon","t":"入力値をチェックすれば防げるのだ？","start":34.8,"end":37.47},{"s":"metan","t":"それは補助的な対策ね。根本的な対策はプレースホルダ。バインド機構やプリペアドステートメントとも呼ぶわ。","start":37.92,"end":45.11},{"s":"metan","t":"SQLの形を先に決めておいて、入力は、ただのデータとして当てはめるから、命令として解釈されないの。","start":45.36,"end":52.82},{"s":"metan","t":"あわせて、データベースのアカウントの権限を最小にしておくと、被害を小さくできるわ。","start":53.07,"end":58.79},{"s":"zundamon","t":"次はXSS、クロスサイトスクリプティングなのだ。","start":59.24,"end":63.38},{"s":"metan","t":"脆弱なサイトに悪意のあるスクリプトを埋め込んで、閲覧者のブラウザで実行させる攻撃よ。","start":63.83,"end":69.81},{"s":"metan","t":"Cookieが盗まれて、なりすましに使われることがあるわ。","start":70.06,"end":73.57},{"s":"metan","t":"根本的な対策は、出力するときのエスケープ。たとえば不等号の記号を、ただの文字として表示されるように置き換えるの。","start":73.82,"end":81.86},{"s":"metan","t":"補助として、CookieにHttpOnly属性を付けたり、CSPで読み込めるスクリプトを制限したりするわ。","start":82.11,"end":88.95},{"s":"zundamon","t":"CSRFは、XSSと名前が似ていて、ごちゃごちゃになるのだ。","start":89.4,"end":95.02},{"s":"metan","t":"CSRFは、ログイン中の利用者に罠ページを踏ませて、本人の意図しない送金や投稿を正規サイトへ送らせる攻撃よ。","start":95.47,"end":103.92},{"s":"metan","t":"スクリプトを動かす必要はなくて、リクエストを偽造させるのがポイント。フォージェリは偽造という意味ね。","start":104.17,"end":110.59},{"s":"metan","t":"対策は、推測できないトークンをフォームに埋め込んで照合すること。","start":110.84,"end":115.14},{"s":"metan","t":"重要な操作の前に再認証を求めることや、CookieのSameSite属性も有効よ。","start":115.39,"end":121.06},{"s":"zundamon","t":"XSSはスクリプトを埋め込む、CSRFはリクエストを偽造させる、なのだ！","start":121.51,"end":128.18},{"s":"metan","t":"その覚え方で完璧よ。","start":128.63,"end":130.22},{"s":"metan","t":"もう一つ、セッション固定化攻撃も押さえておきましょう。対策は、ログインに成功したときにセッションIDを再発行することよ。","start":130.47,"end":138.78},{"s":"zundamon","t":"ランサムウェアも怖いのだ。","start":139.23,"end":141.0},{"s":"metan","t":"ファイルを暗号化して使えなくし、復旧と引き換えに身代金を要求するマルウェアね。","start":141.45,"end":147.04},{"s":"metan","t":"IPAの「情報セキュリティ10大脅威2026」の組織編でも、ランサム攻撃による被害が1位よ。","start":147.29,"end":154.77},{"s":"metan","t":"最近は、暗号化に加えて、盗んだデータの公開も予告する二重脅迫が多いわ。","start":155.02,"end":160.94},{"s":"metan","t":"VPN装置の脆弱性を突いて侵入されることも多いから、早めのパッチ適用と多要素認証が大切ね。","start":161.19,"end":168.33},{"s":"zundamon","t":"バックアップを取っておけば、もう安心なのだ。","start":168.78,"end":172.03},{"s":"metan","t":"そこがひっかけよ。ネットワークにつながったままのバックアップは、一緒に暗号化されるおそれがあるの。","start":172.48,"end":178.69},{"s":"metan","t":"オフラインのバックアップを取って、復元の手順も訓練しておくのが正解ね。","start":178.94,"end":183.7},{"s":"metan","t":"感染してしまったら、その端末をネットワークから切り離して、被害の広がりを封じ込めるわ。","start":183.95,"end":189.9},{"s":"metan","t":"パスワードへの攻撃も一つだけ。パスワードリスト攻撃は、他のサイトから漏れたIDとパスワードの組を使う攻撃よ。","start":190.15,"end":197.81},{"s":"metan","t":"対策はアカウントロックより、パスワードを使い回さないことと、多要素認証ね。","start":198.06,"end":203.48},{"s":"metan","t":"では、ミニクイズよ。第1問。SQLインジェクションの根本的な対策は何かしら。","start":203.73,"end":209.94},{"s":"zundamon","t":"入力値チェック……じゃなくて、プレースホルダなのだ！","start":213.89,"end":217.9},{"s":"metan","t":"正解。入力値チェックは補助的な対策だったわね。","start":218.35,"end":221.92},{"s":"metan","t":"第2問。推測できないトークンをフォームに埋め込んで照合する。これはどの攻撃への対策？","start":222.17,"end":228.47},{"s":"metan","t":"答えはCSRFよ。罠ページからは正しいトークンを送れないから、偽のリクエストを見分けられるの。","start":232.22,"end":239.06},{"s":"metan","t":"第3問。ランサムウェアへの備えとして適切なのは、常に接続したバックアップと、オフラインのバックアップのどちら？","start":239.31,"end":247.12},{"s":"zundamon","t":"オフラインのバックアップなのだ。つながっていると、一緒に暗号化されちゃうのだ。","start":251.07,"end":256.88},{"s":"metan","t":"その通りよ。","start":257.33,"end":258.17},{"s":"metan","t":"今日のまとめよ。一つ目。SQLインジェクションはプレースホルダ、XSSは出力時のエスケープが根本的な対策。","start":258.42,"end":266.77},{"s":"metan","t":"二つ目。CSRFはリクエストの偽造。トークンの照合と再認証で防ぐ。","start":267.02,"end":272.54},{"s":"metan","t":"三つ目。ランサムウェアには、オフラインのバックアップと復元訓練、そして脆弱性対策と多要素認証。","start":272.79,"end":279.91},{"s":"zundamon","t":"攻撃と対策は、セットで覚えるのだ！","start":280.36,"end":283.49},{"s":"metan","t":"次回は、認証とネットワークセキュリティよ。またね。","start":283.94,"end":287.37}]},{"id":"ep11","file":"ep11_auth-network-security.mp3","title":"第11回 認証とネットワークセキュリティ","summary":"多要素認証、TLS、ファイアウォール・WAF・IDS・IPS、送信ドメイン認証（SPF・DKIM・DMARC）、ゼロトラストの役割の違いを整理します。","related":["../01_テクノロジ系/08_情報セキュリティ.md"],"duration":322.3,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第11回は「認証とネットワークセキュリティ」。守りの技術を一気に見ていくわね。","start":0.0,"end":7.58},{"s":"zundamon","t":"ずんだもんなのだ。機械の名前がアルファベットばかりで、目が回りそうなのだ。","start":8.03,"end":13.52},{"s":"metan","t":"それぞれ「何を見て、何をするか」で区別すれば大丈夫よ。","start":13.97,"end":18.41},{"s":"zundamon","t":"多要素認証って、パスワードを2回入れることなのだ？","start":18.86,"end":22.99},{"s":"metan","t":"違うわ。認証の要素は、知識情報、所持情報、生体情報の三つよ。","start":23.44,"end":29.28},{"s":"metan","t":"パスワードは知識、スマートフォンやICカードは所持、指紋や顔は生体ね。","start":29.53,"end":34.84},{"s":"metan","t":"異なる要素を二つ以上組み合わせるのが、多要素認証よ。","start":35.09,"end":38.95},{"s":"metan","t":"「パスワードと秘密の質問」は、どちらも知識情報。二段階ではあっても、多要素認証ではないわ。","start":39.2,"end":46.37},{"s":"zundamon","t":"回数じゃなくて、種類が違うことが大事なのだ。","start":46.82,"end":50.39},{"s":"metan","t":"そうよ。さらにFIDOやパスキーは、端末の中の秘密鍵で署名する方式で、フィッシングに強いの。","start":50.84,"end":59.62},{"s":"zundamon","t":"TLSは、何をしてくれるのだ？","start":60.07,"end":62.9},{"s":"metan","t":"TCPの上で、通信の暗号化、改ざんの検出、サーバの認証をするプロトコルよ。HTTPSで使われているわね。","start":63.35,"end":72.41},{"s":"metan","t":"今の主流はTLS1.2と1.3。SSLや古いTLSは脆弱なので使わないわ。","start":72.66,"end":79.23},{"s":"metan","t":"TLS1.3では、毎回使い捨ての共通鍵を共有するの。","start":79.48,"end":84.08},{"s":"metan","t":"だから、サーバの秘密鍵が後で漏れても、過去の通信は解読されない。この性質を前方秘匿性というわ。","start":84.33,"end":91.72},{"s":"metan","t":"ひっかけ注意。TLSが守るのは通信経路よ。サーバに保存されたデータや、端末に入り込んだマルウェアからは守れないわ。","start":91.97,"end":100.58},{"s":"zundamon","t":"ファイアウォールとWAFとIDSの違いが、分からないのだ。","start":101.03,"end":106.09},{"s":"metan","t":"ファイアウォールは、IPアドレスやポート番号などを見て、通信を許可したり遮断したりする仕組みよ。","start":106.54,"end":112.81},{"s":"metan","t":"ルールは上から順に評価するわ。最後に「すべて拒否」を置いて、必要な通信だけを許可するのが基本ね。","start":113.06,"end":120.33},{"s":"metan","t":"WAFは、Webアプリへの通信の中身を検査して、SQLインジェクションやXSSを遮断するの。","start":120.58,"end":129.06},{"s":"metan","t":"IDSは、不正な通信を検知して、管理者に知らせるだけ。検知して遮断までするのがIPSよ。","start":129.31,"end":136.43},{"s":"zundamon","t":"IDSは見張り番、IPSは門番なのだ。","start":136.88,"end":140.76},{"s":"metan","t":"いい例えね。それから、公開するサーバはDMZに置き、顧客情報を持つデータベースは内部側に置くのよ。","start":141.21,"end":148.73},{"s":"zundamon","t":"なりすましメールは、どうやって防ぐのだ？","start":149.18,"end":152.26},{"s":"metan","t":"送信ドメイン認証を使うわ。SPFは、送信側ドメインのDNSに、正規の送信サーバのIPアドレスを登録しておく方式よ。","start":152.71,"end":162.37},{"s":"metan","t":"DKIMは、送信側のメールサーバが秘密鍵で署名を付け、受信側がDNSの公開鍵で検証する方式。途中の改ざんも分かるわ。","start":162.62,"end":175.02},{"s":"metan","t":"DMARCは、SPFとDKIMの結果に加えて、利用者に見えるFromのドメインが一致するかを確かめるの。","start":175.27,"end":184.76},{"s":"metan","t":"失敗したときの扱いは送信側がDNSで宣言するわ。何もしないnone、隔離するquarantine、拒否するrejectの三つよ。","start":185.01,"end":196.87},{"s":"zundamon","t":"SPFはIPアドレス、DKIMは署名、DMARCはその結果をまとめて方針を決める、なのだ。","start":197.32,"end":206.71},{"s":"metan","t":"そうよ。どれも本文の暗号化はしない点に注意してね。","start":207.16,"end":210.76},{"s":"zundamon","t":"最後は、ゼロトラストなのだ。","start":211.21,"end":213.49},{"s":"metan","t":"社内ネットワークだから安全とは考えず、すべてのアクセスを信頼せずに、毎回検証する考え方よ。","start":213.94,"end":221.15},{"s":"metan","t":"クラウドやテレワークが広がって、内と外の境界があいまいになったことが背景ね。","start":221.4,"end":226.57},{"s":"metan","t":"利用者の認証、端末の状態、場所や時刻などをもとに、アクセスのたびに許可するかを判断するの。","start":226.82,"end":233.55},{"s":"zundamon","t":"社内にいても、毎回チェックされるのだ。","start":234.0,"end":236.93},{"s":"metan","t":"では、ミニクイズよ。第1問。パスワードと、スマートフォンに届く確認コード。これは多要素認証かしら？","start":237.38,"end":245.26},{"s":"metan","t":"答えは、多要素認証よ。パスワードは知識情報、スマートフォンは所持情報で、種類が違うからね。","start":249.01,"end":256.29},{"s":"metan","t":"第2問。不正な通信を検知して管理者に通知するけれど、遮断はしない仕組みは何？","start":256.54,"end":262.72},{"s":"zundamon","t":"見張り番のIDSなのだ！","start":266.67,"end":268.73},{"s":"metan","t":"正解よ。","start":269.18,"end":269.98},{"s":"metan","t":"第3問。送信側ドメインのDNSに、正規の送信サーバのIPアドレスを登録しておく技術は何かしら。","start":270.23,"end":277.99},{"s":"metan","t":"答えはSPFよ。署名を使うのはDKIMだったわね。","start":281.74,"end":286.24},{"s":"metan","t":"今日のまとめよ。一つ目。多要素認証は、知識・所持・生体のうち、異なる要素を組み合わせる。","start":286.49,"end":294.1},{"s":"metan","t":"二つ目。ファイアウォールはアドレスとポート、WAFはWebの中身。IDSは検知だけ、IPSは遮断まで。","start":294.35,"end":303.11},{"s":"metan","t":"三つ目。メールはSPF・DKIM・DMARCで送信元を確かめ、ゼロトラストではすべてのアクセスを毎回検証する。","start":303.36,"end":314.0},{"s":"zundamon","t":"守りの道具の使い分け、すっきりしたのだ！","start":314.45,"end":317.73},{"s":"metan","t":"次回は、開発プロセスとテスト技法よ。またね。","start":318.18,"end":321.54}]},{"id":"ep12","file":"ep12_dev-test.mp3","title":"第12回 開発プロセスとテスト技法","summary":"ウォーターフォール・V字・プロトタイピング・アジャイルの特徴と、テスト工程、スタブとドライバ、ホワイトボックス・ブラックボックスの技法を学びます。","related":["../01_テクノロジ系/09_システム開発技術.md"],"duration":272.5,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第12回は「開発プロセスとテスト技法」を学ぶわね。","start":0.0,"end":6.12},{"s":"zundamon","t":"ずんだもんなのだ。テストって、動かしてみるだけじゃないのだ？","start":6.57,"end":11.03},{"s":"metan","t":"実はテストにも、きちんとした技法があるの。まずは開発の進め方から見ていきましょう。","start":11.48,"end":17.09},{"s":"zundamon","t":"開発の進め方って、いろいろあるのだ？","start":17.54,"end":20.83},{"s":"metan","t":"代表はウォーターフォールモデルよ。要件定義、設計、プログラミング、テストと順番に進め、原則として前の工程に戻らないの。","start":21.28,"end":30.78},{"s":"metan","t":"要件がはっきりしていて、変更が少ない開発に向いているわ。","start":31.03,"end":35.1},{"s":"metan","t":"それを発展させたのがV字モデル。設計の工程と、それを確かめるテストの工程を対応させるの。","start":35.35,"end":42.08},{"s":"metan","t":"内部設計は単体テスト、外部設計は結合テスト、要件定義はシステムテストや運用テストで検証するわ。","start":42.33,"end":49.71},{"s":"metan","t":"要件があいまいなら、早めに試作品を見せて確認するプロトタイピングモデルが向いているわね。","start":49.96,"end":55.72},{"s":"zundamon","t":"アジャイルも聞いたことがあるのだ。","start":56.17,"end":58.25},{"s":"metan","t":"アジャイル開発は、短い期間の反復で、動くソフトウェアを少しずつ届ける進め方よ。変化への対応を重視するの。","start":58.7,"end":66.69},{"s":"metan","t":"ひっかけ注意。アジャイルは「ドキュメントが不要」という意味ではないわ。動くソフトウェアを、より重視するということよ。","start":66.94,"end":74.77},{"s":"zundamon","t":"テストの工程も、順番があるのだ？","start":75.22,"end":78.27},{"s":"metan","t":"ええ。部品ごとの単体テスト、部品をつなぐ結合テスト、全体を確かめるシステムテストの順よ。","start":78.72,"end":86.02},{"s":"metan","t":"最後に、利用者が実際の業務で確かめる運用テストや、発注者の受入れテストがあるわ。","start":86.27,"end":92.37},{"s":"zundamon","t":"結合テストで、まだできていない部品があったらどうするのだ？","start":92.82,"end":97.22},{"s":"metan","t":"上から順につなぐトップダウンテストでは、未完成の下位モジュールの代わりにスタブを使うの。","start":97.67,"end":103.08},{"s":"metan","t":"下から順につなぐボトムアップテストでは、上位の代わりに呼び出す役のドライバを使うわ。","start":103.33,"end":108.62},{"s":"zundamon","t":"スタブは下の代役、ドライバは上の代役なのだ。運転手が車を動かすイメージなのだ！","start":109.07,"end":115.84},{"s":"metan","t":"その覚え方でいいわ。それから、修正した後に、変更していない部分へ悪影響がないかを確かめるのが回帰テストよ。","start":116.29,"end":124.09},{"s":"zundamon","t":"ホワイトボックスとブラックボックスって、何の箱なのだ？","start":124.54,"end":128.61},{"s":"metan","t":"ホワイトボックステストは、プログラムの内部構造、つまり分岐や命令に注目してテストケースを作る技法よ。","start":129.06,"end":136.17},{"s":"metan","t":"すべての命令を1回は通す命令網羅、すべての判定の真と偽を1回ずつ通す判定網羅などがあるわ。","start":136.42,"end":143.49},{"s":"metan","t":"判定の中の、個々の条件の真と偽を通すのが条件網羅。","start":143.74,"end":147.94},{"s":"metan","t":"ひっかけ注意。条件網羅を満たしても、判定網羅を満たすとは限らないの。","start":148.19,"end":153.16},{"s":"metan","t":"ブラックボックステストは、中身を見ずに、仕様の入力と出力に注目する技法よ。","start":153.41,"end":159.0},{"s":"metan","t":"例えば、0歳から17歳は子ども料金、18歳から64歳は大人料金、65歳以上はシニア料金という仕様を考えましょう。","start":159.25,"end":169.36},{"s":"metan","t":"同値分割では、グループごとに代表値を一つずつ選ぶの。マイナスの年齢のような、誤った入力のグループも忘れずにね。","start":169.61,"end":177.87},{"s":"metan","t":"境界値分析では、境目の前後を選ぶわ。17歳と18歳、64歳と65歳、そして0歳とマイナス1歳よ。","start":178.12,"end":187.15},{"s":"zundamon","t":"なんで境目ばかり狙うのだ？","start":187.6,"end":189.86},{"s":"metan","t":"「より小さい」と「以下」の書き間違いは、境目でしか見つからないからよ。","start":190.31,"end":195.75},{"s":"metan","t":"では、ミニクイズよ。第1問。トップダウンテストで、未完成の下位モジュールの代わりに使うものは何？","start":196.0,"end":203.18},{"s":"zundamon","t":"下の代役だから、スタブなのだ！","start":207.13,"end":209.69},{"s":"metan","t":"正解よ。","start":210.14,"end":210.94},{"s":"metan","t":"第2問。「20歳以上は成人」という仕様。境界値分析で選ぶ二つの年齢は何歳と何歳かしら。","start":211.19,"end":218.66},{"s":"metan","t":"答えは、19歳と20歳よ。境目のすぐ手前と、ちょうど境目の年齢ね。","start":222.41,"end":228.21},{"s":"metan","t":"第3問。プログラムを修正した後、変更していない部分に悪影響がないかを確かめるテストは？","start":228.46,"end":235.31},{"s":"metan","t":"答えは回帰テスト、リグレッションテストよ。何度も繰り返すから、自動化と相性がいいの。","start":239.06,"end":245.05},{"s":"metan","t":"今日のまとめよ。一つ目。V字モデルでは、上流の設計ほど、後のテストで検証される。","start":245.3,"end":251.66},{"s":"metan","t":"二つ目。スタブは呼ばれる下位の代役、ドライバは呼び出す上位の代役。","start":251.91,"end":256.69},{"s":"metan","t":"三つ目。ホワイトボックスは内部構造、ブラックボックスは仕様に注目。境界値は境目の前後を選ぶ。","start":256.94,"end":264.13},{"s":"zundamon","t":"テストにも作戦があるのだ！","start":264.58,"end":266.57},{"s":"metan","t":"次回は、プロジェクトマネジメントのクリティカルパスとEVMよ。またね。","start":267.02,"end":271.7}]},{"id":"ep13","file":"ep13_pm-evm-cpm.mp3","title":"第13回 プロジェクトマネジメント：クリティカルパスとEVM","summary":"アローダイアグラムのクリティカルパスと余裕日数、スケジュール短縮の2手法、EVMのPV・EV・ACと差異・効率指数の計算を、口頭でたどれる数値で練習します。","related":["../02_マネジメント系/01_プロジェクトマネジメント.md","../05_まとめ・横断資料/01_計算問題公式集.md"],"duration":300.3,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第13回は、プロジェクトマネジメントの計算の定番、クリティカルパスとEVMよ。","start":0.0,"end":8.04},{"s":"zundamon","t":"ずんだもんなのだ。計算問題は、聞いただけで眠くなるのだ。","start":8.49,"end":13.15},{"s":"metan","t":"今日は簡単な数字で、考え方の筋道をつかみましょう。","start":13.6,"end":17.53},{"s":"zundamon","t":"クリティカルパスって、何なのだ？","start":17.98,"end":20.57},{"s":"metan","t":"始点から終点までの経路のうち、所要日数が一番長い経路よ。この上の作業が1日遅れると、全体も1日遅れるの。","start":21.02,"end":30.08},{"s":"metan","t":"例題よ。作業Aが3日、作業Bが5日。Aが終わったら、Cが4日、Dが6日。","start":30.33,"end":37.39},{"s":"metan","t":"BとCの両方が終わったらEが3日。DとEの両方が終わったらFが2日。","start":37.64,"end":42.92},{"s":"metan","t":"経路は3本。A、C、E、Fで12日。A、D、Fで11日。B、E、Fで10日よ。","start":43.17,"end":54.64},{"s":"zundamon","t":"一番短い10日で終わるんじゃないのだ？","start":55.09,"end":58.02},{"s":"metan","t":"そこが勘違いしやすいところ。全部の作業が終わらないと完了しないから、一番長い経路が全体の日数を決めるの。","start":58.47,"end":66.2},{"s":"metan","t":"だから全体は12日。A、C、E、Fがクリティカルパスよ。","start":66.45,"end":72.41},{"s":"metan","t":"計算の手順も押さえておきましょう。最早結合点時刻は、始点から前向きに足していき、合流するところでは最大値をとるわ。","start":72.66,"end":83.29},{"s":"metan","t":"最遅結合点時刻は、終点から後ろ向きに引いていき、分かれるところでは最小値をとるの。","start":83.54,"end":91.02},{"s":"metan","t":"余裕も見てみましょう。Bは2日、Dは1日までなら遅れても、全体は12日のまま。これを全余裕というわ。","start":91.27,"end":99.21},{"s":"zundamon","t":"急いで終わらせたいときは、どうするのだ？","start":99.66,"end":102.67},{"s":"metan","t":"要員や費用を追加して短くするのがクラッシング。お金で時間を買う方法ね。","start":103.12,"end":108.22},{"s":"metan","t":"本来は順番に行う作業を重ねて進めるのがファストトラッキング。手戻りのリスクで時間を買う方法よ。","start":108.47,"end":115.05},{"s":"metan","t":"ひっかけ注意。クリティカルパス以外の作業を短くしても、全体は短くならないわ。","start":115.3,"end":121.07},{"s":"zundamon","t":"次はEVMなのだ。","start":121.52,"end":123.29},{"s":"metan","t":"EVMは、計画、出来高、実際のコストの三つを、同じ金額の単位で比べる手法よ。","start":123.74,"end":130.56},{"s":"metan","t":"PVは、今までに予定していた作業の予算。EVは、実際に終わった作業の予算。ACは、実際にかかった費用よ。","start":130.81,"end":139.74},{"s":"metan","t":"差異は「EVひく何か」、指数は「EVわる何か」。スケジュールはPVと、コストはACと比べるの。","start":139.99,"end":147.61},{"s":"zundamon","t":"全部EVが主役なのだ。","start":148.06,"end":150.07},{"s":"metan","t":"例題よ。総予算1,000万円で、PVが400万円、EVが320万円、ACが360万円。","start":150.52,"end":159.39},{"s":"metan","t":"スケジュール差異SVは、EVひくPVで、320ひく400、マイナス80万円。遅れているわ。","start":159.64,"end":167.34},{"s":"metan","t":"コスト差異CVは、EVひくACで、320ひく360、マイナス40万円。予算超過ね。","start":167.59,"end":175.72},{"s":"metan","t":"スケジュール効率指数SPIは、EVわるPVで、320わる400、0.8。1より小さいから遅れよ。","start":175.97,"end":187.78},{"s":"metan","t":"コスト効率指数CPIは、EVわるACで、320わる360、およそ0.89。こちらも1より小さいわね。","start":188.03,"end":197.49},{"s":"metan","t":"このまま同じコスト効率が続くと、完成時の総コストは1,125万円になる見込みよ。","start":197.74,"end":203.77},{"s":"zundamon","t":"マイナスや1未満は、悪いサインなのだ。","start":204.22,"end":207.34},{"s":"metan","t":"ひっかけ注意。PVとACを直接比べても意味がないわ。","start":207.79,"end":212.02},{"s":"metan","t":"予定より多く使ったのが、進みすぎたせいか、効率が悪いせいか、区別できないからよ。","start":212.27,"end":218.27},{"s":"metan","t":"では、ミニクイズよ。第1問。クリティカルパスではない作業を短縮すると、全体の日数はどうなるかしら。","start":218.52,"end":226.16},{"s":"metan","t":"答えは、短くならない、よ。一番長い経路が変わらないからね。","start":229.91,"end":235.0},{"s":"metan","t":"第2問。PVが200万円、EVが180万円。SPIはいくつ？","start":235.25,"end":242.65},{"s":"zundamon","t":"180わる200で、0.9なのだ。1より小さいから遅れなのだ！","start":247.1,"end":253.03},{"s":"metan","t":"正解よ。","start":253.48,"end":254.28},{"s":"metan","t":"第3問。同じプロジェクトで、ACが200万円だったら、コスト差異はいくら？","start":254.53,"end":260.15},{"s":"metan","t":"EVひくACで、180ひく200、マイナス20万円。予算超過よ。","start":264.4,"end":270.4},{"s":"metan","t":"今日のまとめよ。一つ目。クリティカルパスは最長の経路で、全体の日数を決める。","start":270.65,"end":276.56},{"s":"metan","t":"二つ目。短縮は、お金で時間を買うクラッシングと、重ねて進めるファストトラッキング。","start":276.81,"end":282.64},{"s":"metan","t":"三つ目。EVMはEVが主役。差異はEVひく何か、指数はEVわる何かで、マイナスや1未満は悪いサイン。","start":282.89,"end":291.48},{"s":"zundamon","t":"計算も、筋道が分かれば怖くないのだ！","start":291.93,"end":295.26},{"s":"metan","t":"次回は、サービスマネジメントとシステム監査よ。またね。","start":295.71,"end":299.46}]},{"id":"ep14","file":"ep14_service-audit.mp3","title":"第14回 サービスマネジメントとシステム監査","summary":"SLA・OLA・UCの違い、稼働率と許容停止時間、インシデント管理と問題管理、変更・構成・リリース管理、システム監査の独立性・監査証拠・フォローアップを整理します。","related":["../02_マネジメント系/02_サービスマネジメント.md","../02_マネジメント系/03_システム監査.md"],"duration":276.8,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第14回は「サービスマネジメントとシステム監査」を学ぶわね。","start":0.0,"end":6.72},{"s":"zundamon","t":"ずんだもんなのだ。どっちも、似たような管理の言葉がいっぱいで混乱するのだ。","start":7.17,"end":12.78},{"s":"metan","t":"今日は、それぞれの「目的」に注目して区別していきましょう。","start":13.23,"end":17.63},{"s":"zundamon","t":"SLAって、何の約束なのだ？","start":18.08,"end":21.13},{"s":"metan","t":"SLAは、サービスの提供者と顧客が、サービスの内容と水準を合意した文書よ。稼働率や応答時間などを決めるの。","start":21.58,"end":30.01},{"s":"metan","t":"社内の他部門との合意はOLA、外部の供給者との契約はUC、裏付け契約というわ。","start":30.26,"end":37.0},{"s":"zundamon","t":"SLAは顧客、OLAは社内、UCは外注なのだ。","start":37.45,"end":42.53},{"s":"metan","t":"その通り。例えば、月の稼働率99.9%以上と約束したとしましょう。1か月を30日とすると、総時間は43,200分よ。","start":42.98,"end":53.73},{"s":"metan","t":"止まってよいのは、その0.1%だから、43.2分。1か月の停止を43分ほどに抑える必要があるわ。","start":53.98,"end":62.7},{"s":"zundamon","t":"障害が起きたら、まず原因を突き止めるのだ？","start":63.15,"end":66.74},{"s":"metan","t":"そこがよく出るひっかけよ。インシデント管理の目的は、サービスをできるだけ早く元に戻すこと。","start":67.19,"end":73.31},{"s":"metan","t":"回避策を使ってでも、まず復旧させるの。根本原因を突き止めて再発を防ぐのは、問題管理の役割よ。","start":73.56,"end":81.22},{"s":"metan","t":"問題管理は、恒久対策を自分で実施するのではなく、変更要求を出して変更管理に渡すわ。","start":81.47,"end":88.21},{"s":"metan","t":"変更管理は、変更を評価して承認する。リリース管理は、承認された変更を本番環境に届ける。","start":88.46,"end":95.85},{"s":"metan","t":"構成管理は、システムを構成する要素とその関係を、構成管理データベースに正しく記録しておくの。","start":96.1,"end":103.0},{"s":"zundamon","t":"やってよいかを決める、実際に届ける、今の状態を記録する、なのだ。","start":103.45,"end":109.53},{"s":"metan","t":"完璧な言い換えね。","start":109.98,"end":111.25},{"s":"zundamon","t":"次はシステム監査なのだ。監査って、何をするのだ？","start":111.7,"end":116.1},{"s":"metan","t":"専門性と客観性を持つ監査人が、ITシステムの管理が適切かを検証して、保証や改善の助言をすることよ。","start":116.55,"end":124.37},{"s":"metan","t":"システム監査基準は、監査人がどう監査するかという行為の規範。","start":124.62,"end":128.9},{"s":"metan","t":"システム管理基準は、組織がITを管理するための実践の規範で、監査のときの判断の尺度にもなるわ。","start":129.15,"end":136.29},{"s":"zundamon","t":"監査人のルールと、組織のものさしなのだ。","start":136.74,"end":140.04},{"s":"metan","t":"そうよ。そして一番大事なのが独立性。監査人は、監査する対象から独立していないといけないの。","start":140.49,"end":147.57},{"s":"metan","t":"例えば、そのシステムの開発に参加していた人が監査を担当するのは、独立性を損なうわ。","start":147.82,"end":154.08},{"s":"metan","t":"監査の流れは、計画、予備調査、本調査、評価と結論、報告、そしてフォローアップよ。","start":154.33,"end":161.53},{"s":"metan","t":"本調査で集めた監査証拠と判断の過程は、監査人自身が監査調書に記録するの。","start":161.78,"end":167.56},{"s":"metan","t":"証拠としては、口頭の説明だけより、監査人が自分で観察したものや、記録やログのほうが強いわ。","start":167.81,"end":174.9},{"s":"zundamon","t":"問題が見つかったら、監査人が直してあげるのだ？","start":175.35,"end":179.26},{"s":"metan","t":"それはだめよ。改善を実施する責任は、監査を受けた部門にあるの。","start":179.71,"end":184.42},{"s":"metan","t":"監査人が自分で直すと、次の監査で自分の作業を評価することになって、独立性が損なわれるわ。","start":184.67,"end":191.52},{"s":"metan","t":"監査人は、フォローアップで改善の状況を確認するのが役割よ。","start":191.77,"end":196.25},{"s":"metan","t":"では、ミニクイズよ。第1問。インシデント管理で最も優先する目的は何かしら。","start":196.5,"end":202.61},{"s":"zundamon","t":"原因究明じゃなくて、サービスを早く元に戻すことなのだ！","start":206.56,"end":211.09},{"s":"metan","t":"正解よ。原因究明は問題管理だったわね。","start":211.54,"end":215.05},{"s":"metan","t":"第2問。対象システムの開発プロジェクトにいた人が、そのシステムを監査する。何が問題かしら。","start":215.3,"end":222.13},{"s":"metan","t":"答えは、独立性が損なわれることよ。自分が関わったものを、公正に評価できないからね。","start":225.88,"end":232.15},{"s":"metan","t":"第3問。監査で指摘した事項の改善を実施する責任は、誰にある？","start":232.4,"end":237.56},{"s":"metan","t":"答えは、監査を受けた部門よ。監査人は、改善の状況を確認する立場ね。","start":241.31,"end":247.12},{"s":"metan","t":"今日のまとめよ。一つ目。SLAは顧客、OLAは社内、UCは外部の供給者との取り決め。","start":247.37,"end":254.83},{"s":"metan","t":"二つ目。インシデント管理はまず復旧、問題管理は根本原因と再発防止。","start":255.08,"end":260.74},{"s":"metan","t":"三つ目。監査人は独立性が大切。改善するのは監査を受けた部門で、監査人はフォローアップで確認する。","start":260.99,"end":268.75},{"s":"zundamon","t":"目的で区別すれば、もう迷わないのだ！","start":269.2,"end":272.29},{"s":"metan","t":"次回は、経営戦略と会計よ。またね。","start":272.74,"end":276.03}]},{"id":"ep15","file":"ep15_strategy-accounting.mp3","title":"第15回 経営戦略と会計","summary":"SWOT分析とPPMで事業を整理する考え方と、損益分岐点・安全余裕率の計算、ROE・ROA・流動比率・自己資本比率などの財務指標を学びます。","related":["../03_ストラテジ系/02_経営戦略とマーケティング.md","../03_ストラテジ系/03_企業活動と会計.md","../05_まとめ・横断資料/01_計算問題公式集.md"],"duration":297.0,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第15回は「経営戦略と会計」。ストラテジ系の得点源ね。","start":0.0,"end":7.01},{"s":"zundamon","t":"ずんだもんなのだ。経営なんて、ボクにはまだ早い気がするのだ。","start":7.46,"end":12.29},{"s":"metan","t":"大丈夫。分析の枠組みと、計算の公式さえ押さえれば解けるわ。","start":12.74,"end":17.61},{"s":"zundamon","t":"まず、SWOT分析って何なのだ？","start":18.06,"end":21.57},{"s":"metan","t":"自社の内部環境と、外部環境の二つの軸で、現状を整理する手法よ。","start":22.02,"end":27.38},{"s":"metan","t":"内部のプラスが強み、マイナスが弱み。外部のプラスが機会、マイナスが脅威ね。","start":27.63,"end":33.14},{"s":"zundamon","t":"法律が変わるのは、会社の弱みなのだ？","start":33.59,"end":36.87},{"s":"metan","t":"それがひっかけよ。法改正や競合の新製品、為替は、自社では変えられないから外部環境。機会か脅威になるわ。","start":37.32,"end":45.57},{"s":"metan","t":"弱みに入るのは、自社の営業力不足のような、内部のマイナス要因よ。","start":45.82,"end":52.04},{"s":"metan","t":"四つを掛け合わせるクロスSWOT分析もあるわ。強みで機会をつかむのがSO戦略、最悪の事態を避けるのがWT戦略よ。","start":52.29,"end":64.37},{"s":"zundamon","t":"PPMは、どんな分析なのだ？","start":64.82,"end":67.67},{"s":"metan","t":"市場成長率と、相対的市場占有率の二つの軸で事業を四つに分けて、お金の配分を決める手法よ。","start":68.12,"end":75.49},{"s":"metan","t":"相対的市場占有率は、自社のシェアを、最大の競合のシェアでわったものよ。","start":75.74,"end":81.15},{"s":"metan","t":"自社が30%、最大の競合が20%なら、30わる20で1.5。1より大きいから「高い」と見るわ。","start":81.4,"end":90.42},{"s":"metan","t":"成長率もシェアも高いのが花形。成長率は低いけれどシェアが高いのが金のなる木で、資金を生み出すの。","start":90.67,"end":97.83},{"s":"metan","t":"成長率は高いのにシェアが低いのが問題児。どちらも低いのが負け犬よ。","start":98.08,"end":102.94},{"s":"zundamon","t":"金のなる木で稼いだお金を、問題児に投資して、花形に育てるのだ。","start":103.39,"end":108.86},{"s":"metan","t":"その通り。軸は「市場規模」や「利益率」ではないから注意してね。","start":109.31,"end":115.25},{"s":"zundamon","t":"損益分岐点は、計算が出てくるのだ……。","start":115.7,"end":119.03},{"s":"metan","t":"損益分岐点は、利益がちょうどゼロになる売上高よ。公式は、固定費わる、1ひく変動費率。","start":119.48,"end":126.6},{"s":"metan","t":"例題よ。売上高1,000万円、変動費600万円、固定費300万円。","start":126.85,"end":132.71},{"s":"metan","t":"変動費率は、600わる1,000で0.6。1ひく0.6で、限界利益率は0.4よ。","start":132.96,"end":139.66},{"s":"metan","t":"損益分岐点は、300わる0.4で、750万円になるわ。","start":139.91,"end":145.03},{"s":"zundamon","t":"750万円より売れれば黒字、少なければ赤字なのだ。","start":145.48,"end":150.23},{"s":"metan","t":"そうよ。今の売上1,000万円が750万円まで、つまり25%減っても赤字にならない。これが安全余裕率よ。","start":150.68,"end":159.33},{"s":"metan","t":"損益分岐点を下げるには、固定費を減らすか、変動費率を下げるか、販売価格を上げればいいわ。","start":159.58,"end":166.38},{"s":"zundamon","t":"財務指標も、たくさんあって困るのだ。","start":166.83,"end":169.73},{"s":"metan","t":"収益性の代表はROE、自己資本利益率よ。当期純利益を、自己資本でわって求めるの。","start":170.18,"end":177.34},{"s":"metan","t":"例えば、当期純利益が420万円、自己資本が5,000万円なら、420わる5,000で、ROEは8.4%よ。","start":177.59,"end":187.28},{"s":"metan","t":"ROAは総資産利益率。当期純利益を、総資産でわって求めるわ。","start":187.53,"end":192.85},{"s":"metan","t":"安全性では、流動資産を流動負債で割る流動比率と、自己資本を総資本で割る自己資本比率。どちらも高いほど安全よ。","start":193.1,"end":201.92},{"s":"metan","t":"ひっかけ注意。固定資産を自己資本で割る固定比率は、低いほうが良い指標よ。","start":202.17,"end":207.58},{"s":"metan","t":"借金を増やすとROEは上がりやすいけれど、自己資本比率は下がって、安全性は低くなるわ。","start":207.83,"end":214.58},{"s":"metan","t":"では、ミニクイズよ。第1問。法改正は、SWOT分析ではどこに分類されるかしら。","start":214.83,"end":221.94},{"s":"metan","t":"答えは外部環境。内容によって、機会か脅威になるわ。自社では変えられないからね。","start":225.69,"end":231.68},{"s":"metan","t":"第2問。固定費200万円、変動費率0.6。損益分岐点売上高はいくら？","start":231.93,"end":238.55},{"s":"zundamon","t":"1ひく0.6で0.4。200わる0.4で、500万円なのだ！","start":243.0,"end":248.81},{"s":"metan","t":"正解よ。","start":249.26,"end":250.06},{"s":"metan","t":"第3問。PPMで、市場成長率は低いけれど、相対的市場占有率が高い事業は何と呼ぶ？","start":250.31,"end":258.04},{"s":"metan","t":"答えは金のなる木よ。投資が少なくて済み、資金を生み出す事業ね。","start":261.79,"end":266.42},{"s":"metan","t":"今日のまとめよ。一つ目。SWOTは、自社で変えられる内部と、変えられない外部に分ける。","start":266.67,"end":274.56},{"s":"metan","t":"二つ目。PPMは、市場成長率と相対的市場占有率で事業を分け、金のなる木の資金を問題児へ回す。","start":274.81,"end":283.03},{"s":"metan","t":"三つ目。損益分岐点は、固定費わる、1ひく変動費率。固定比率は低いほど良い。","start":283.28,"end":289.72},{"s":"zundamon","t":"経営も、枠組みと公式で攻略なのだ！","start":290.17,"end":293.62},{"s":"metan","t":"次回は、法務よ。またね。","start":294.07,"end":296.17}]},{"id":"ep16","file":"ep16_law.mp3","title":"第16回 法務","summary":"著作権と特許権の違い、職務著作と委託開発の権利、個人情報保護法の要点、請負・準委任・派遣と偽装請負、2026年1月施行の中小受託取引適正化法（旧：下請法）を整理します。","related":["../03_ストラテジ系/04_法務.md"],"duration":282.0,"cues":[{"s":"metan","t":"こんにちは、四国めたんよ。第16回は「法務」。暗記が多いけれど、理由と一緒に覚えると忘れにくいわ。","start":0.0,"end":7.82},{"s":"zundamon","t":"ずんだもんなのだ。法律の話は、言葉がかたくて苦手なのだ。","start":8.27,"end":13.05},{"s":"metan","t":"大丈夫。試験でよく問われるところだけに絞りましょう。","start":13.5,"end":16.88},{"s":"zundamon","t":"著作権と特許権は、何が違うのだ？","start":17.33,"end":20.67},{"s":"metan","t":"著作権は、作った時点で自動的に発生するの。登録はいらないわ。期間は原則、著作者の死後70年よ。","start":21.12,"end":29.09},{"s":"metan","t":"特許権は、出願して審査を受け、登録して初めて発生するの。期間は出願から20年ね。","start":29.34,"end":36.12},{"s":"metan","t":"プログラムは著作物として守られるけれど、プログラム言語や通信規約、アルゴリズムは守られないわ。","start":36.37,"end":43.04},{"s":"zundamon","t":"どうしてアルゴリズムは守られないのだ？","start":43.49,"end":46.15},{"s":"metan","t":"著作権が守るのは「表現」で、「アイデア」は守らないからよ。","start":46.6,"end":51.73},{"s":"metan","t":"社員が仕事で作ったプログラムは、条件を満たせば会社が著作者になるの。これが職務著作よ。","start":51.98,"end":58.2},{"s":"metan","t":"プログラムの場合は、会社の名前で公表するという条件がいらないのがポイントね。","start":58.45,"end":63.57},{"s":"zundamon","t":"外部の会社にお金を払って作ってもらったら、発注した会社のものなのだ。","start":64.02,"end":69.42},{"s":"metan","t":"それがひっかけよ。請負で作ってもらった場合、特約がなければ、著作権は作った受託者に残るの。","start":69.87,"end":76.56},{"s":"metan","t":"発注者が権利を得たいなら、契約で著作権の譲渡を定めておく必要があるわ。","start":76.81,"end":82.12},{"s":"zundamon","t":"個人情報保護法も、よく出るのだ？","start":82.57,"end":85.5},{"s":"metan","t":"ええ。個人情報は、生存する個人に関する情報よ。亡くなった人の情報は含まないの。","start":85.95,"end":92.64},{"s":"metan","t":"マイナンバーや、指紋や顔をデータにしたものは、それだけで個人を特定できる個人識別符号ね。","start":92.89,"end":99.12},{"s":"metan","t":"病歴や犯罪の経歴などは要配慮個人情報。取得には原則として本人の同意が必要で、オプトアウトによる提供もできないわ。","start":99.37,"end":108.24},{"s":"metan","t":"仮名加工情報は、照合すれば元に戻せる程度の加工で、社内の分析用。第三者提供は原則禁止よ。","start":108.49,"end":116.47},{"s":"metan","t":"匿名加工情報は、元に戻せないように加工したもので、社外に提供できるわ。","start":116.72,"end":122.3},{"s":"zundamon","t":"仮の名前なら戻せるから社内用、名前を隠したら戻せないから社外もOK、なのだ。","start":122.75,"end":129.43},{"s":"zundamon","t":"請負と準委任と派遣は、何が違うのだ？","start":129.68,"end":133.31},{"s":"metan","t":"見るポイントは二つ。何に対してお金を払うかと、誰が作業者に指示を出すかよ。","start":133.76,"end":139.23},{"s":"metan","t":"請負は仕事の完成が目的で、完成の責任があるの。準委任は業務の遂行が目的で、完成の責任はないわ。","start":139.48,"end":148.11},{"s":"metan","t":"どちらも、作業者に指示を出すのは受託者よ。派遣だけは、派遣先が直接指示を出せるの。","start":148.36,"end":154.52},{"s":"metan","t":"請負なのに、発注者が受託者の作業者に直接指示している状態を偽装請負というわ。法律違反よ。","start":154.77,"end":161.81},{"s":"zundamon","t":"最後の、中小受託取引適正化法という名前は、初めて聞いたのだ。","start":162.26,"end":168.04},{"s":"metan","t":"下請法が改正されて、2026年1月1日から、この名前になったの。通称は取適法よ。","start":168.49,"end":175.81},{"s":"metan","t":"親事業者は委託事業者、下請事業者は中小受託事業者と呼び方が変わったわ。","start":176.06,"end":183.09},{"s":"metan","t":"委託事業者は、成果物を受け取った日から60日以内に支払期日を定めないといけないの。","start":183.34,"end":189.4},{"s":"metan","t":"手形での支払いは禁止になり、価格の協議に応じずに一方的に代金を決めることも禁止されたわ。","start":189.65,"end":196.09},{"s":"metan","t":"通常より著しく低い代金を押しつける買いたたきや、発注後の代金の減額も禁止よ。","start":196.34,"end":202.34},{"s":"metan","t":"では、ミニクイズよ。第1問。請負契約で開発したプログラム。特約がない場合、著作権は誰のもの？","start":202.59,"end":210.7},{"s":"zundamon","t":"お金を払った発注者……じゃなくて、作った受託者なのだ！","start":214.65,"end":219.18},{"s":"metan","t":"正解よ。","start":219.63,"end":220.43},{"s":"metan","t":"第2問。請負契約なのに、発注者が受託者のプログラマに直接作業を指示している。これを何という？","start":220.68,"end":228.03},{"s":"metan","t":"答えは偽装請負よ。指示は、受託者の責任者を通して伝えるのが正しいやり方ね。","start":231.78,"end":237.71},{"s":"metan","t":"第3問。取適法で、委託事業者が定める支払期日は、受け取った日から何日以内かしら。","start":237.96,"end":244.58},{"s":"metan","t":"答えは60日以内よ。","start":248.33,"end":250.07},{"s":"metan","t":"今日のまとめよ。一つ目。著作権は登録不要で死後70年、特許権は登録が必要で出願から20年。","start":250.32,"end":258.1},{"s":"metan","t":"二つ目。請負では、特約がなければ著作権は受託者に残る。指示を出すのは受託者で、直接指示は偽装請負。","start":258.35,"end":266.48},{"s":"metan","t":"三つ目。下請法は取適法へ。60日以内の支払い、手形払いの禁止、一方的な代金決定の禁止。","start":266.73,"end":275.2},{"s":"zundamon","t":"理由と一緒なら、法律も覚えられるのだ！","start":275.65,"end":278.75},{"s":"metan","t":"今回もお疲れさま。またね。","start":279.2,"end":281.17}]}];
